// Package analyzer implements the declscope analysis.
package analyzer

import (
	"flag"
	"fmt"
	"go/ast"
	"strings"

	"declscope/internal/checker"
)

const doc = `enforces private and shared pseudo scopes for package-level declarations, methods and struct fields

Subcommands:

   declscope baseline [flags] [packages]
   declscope inspect  [flags] <package>
   declscope survey   [flags] [packages]
   declscope shrink   [flags] [packages]

   declscope skill install   [flags] [skill...]
   declscope skill uninstall [flags] [skill...]
   declscope skill list      [flags] [skill...]

Run a subcommand with -h for its flags.`

// configFlag is the -config flag of the analyzer.
var configFlag string

// New returns the analyzer with its flags.
func New() *checker.Analyzer {
	fs := flag.NewFlagSet("declscope", flag.ExitOnError)
	fs.StringVar(&configFlag, "config", "", "path to a declscope YAML config file (default: nearest .declscope.yaml)")
	return &checker.Analyzer{
		Name:  "declscope",
		Doc:   doc,
		Flags: fs,
		Run:   run,
	}
}

func run(pass *checker.Pass) error {
	rules, err := rulesForPass(pass.Pkg, configFlag)
	if err != nil {
		return err
	}
	var base Baseline
	if path := baselineFrom(pass.Pkg, searchDir(pass.Pkg), rules); path != "" {
		if base, err = LoadBaseline(path); err != nil {
			return err
		}
	}
	res := Analyze(pass, rules, base)
	for _, f := range res.Reported {
		pass.Report(f.diagnostic())
	}
	return nil
}

func (f *finding) diagnostic() checker.Diagnostic {
	d := checker.Diagnostic{
		Pos:      f.pos,
		End:      f.pos,
		Category: f.rule,
		Message:  f.message,
		Related:  f.related,
	}
	if f.fix != nil {
		d.SuggestedFixes = []checker.SuggestedFix{*f.fix}
	}
	return d
}

// Result is the outcome of analyzing one package.
type Result struct {
	Model     *model
	Findings  []*finding // every finding, silenced or not
	Reported  []*finding
	Ignored   map[*finding]bool
	Baselined map[*finding]bool
	// Covered holds the member reports a shown report on their type hides.
	Covered []*finding
}

// Analyze runs every rule on a package.
func Analyze(pass *checker.Pass, rules *Rules, base Baseline) *Result {
	m := newModel(pass, rules)
	res := &Result{Model: m, Ignored: make(map[*finding]bool), Baselined: make(map[*finding]bool)}
	if len(m.files) == 0 {
		if f := m.filterFinding(); f != nil {
			res.Findings = append(res.Findings, f)
			res.Reported = append(res.Reported, f)
		}
		return res
	}

	phase1 := m.declFindings(true)
	phase2 := append([]*finding(nil), m.problems...)
	phase2 = append(phase2, m.unusedScopeFindings(true, phase1)...)
	m.sortByPos(phase2)

	shown := make(map[*finding]bool)
	emit := func(f *finding) {
		if f.coveredBy != nil && shown[f.coveredBy] {
			res.Covered = append(res.Covered, f)
			return
		}
		igs := m.covering(f)
		for _, ig := range igs {
			ig.used = true
		}
		if len(igs) > 0 && (f.rule == "directive" || f.rule == "unused") && !allFileLevel(igs) {
			// Silenced on its declaration, the report never counts.
			return
		}
		res.Findings = append(res.Findings, f)
		if len(igs) > 0 {
			res.Ignored[f] = true
			// A silenced report on a type still covers its members.
			shown[f] = true
			return
		}
		if ns, name, ok := m.baselineKey(f); ok && base.Has(pass.Pkg.PkgPath, f.rule, ns, name) {
			res.Baselined[f] = true
			return
		}
		shown[f] = true
		res.Reported = append(res.Reported, f)
	}
	for _, f := range phase1 {
		emit(f)
	}
	for _, f := range phase2 {
		emit(f)
	}
	reported, silenced := m.unusedIgnoreFindings()
	for _, f := range silenced {
		res.Findings = append(res.Findings, f)
		res.Ignored[f] = true
	}
	for _, f := range reported {
		res.Findings = append(res.Findings, f)
		res.Reported = append(res.Reported, f)
	}
	return res
}

// ancestors lists a target and the targets that contain it.
func ancestors(t *target) []*target {
	var out []*target
	for ; t != nil; t = t.parent {
		out = append(out, t)
	}
	return out
}

// covering lists the ignores that silence a finding.
func (m *model) covering(f *finding) []*directive {
	var out []*directive
	if f.unusedOf {
		dir := f.dir
		file := dir.file
		if !dir.fileLevel && dir.target != nil {
			for _, ig := range dir.target.ignores {
				if ig == dir {
					continue
				}
				if ig.bare && dir.isScope() || !ig.bare && ig.covers("unused") {
					out = append(out, ig)
				}
			}
		}
		for _, ig := range file.ignores {
			if ig != dir && ig.covers("unused") {
				out = append(out, ig)
			}
		}
		return out
	}
	var t *target
	var file *fileInfo
	switch {
	case f.decl != nil:
		t, file = f.decl.target, f.decl.file
	case f.dir != nil:
		file = f.dir.file
		if !f.dir.fileLevel {
			t = f.dir.target
		}
	}
	scope := ancestors(t)
	if f.rule == "directive" && len(scope) > 0 {
		// A problem with a directive is silenced on its own declaration
		// only, never from the type or block around it.
		scope = scope[:1]
	}
	for _, a := range scope {
		for _, ig := range a.ignores {
			if ig.covers(f.rule) {
				out = append(out, ig)
			}
		}
	}
	if file != nil {
		for _, ig := range file.ignores {
			if ig.covers(f.rule) {
				out = append(out, ig)
			}
		}
	}
	return out
}

// silence reports whether an ignore silences f, marking every ignore that
// covers it as used.
func (m *model) silence(f *finding) bool {
	igs := m.covering(f)
	for _, ig := range igs {
		ig.used = true
	}
	return len(igs) > 0
}

// unusedIgnoreFindings reports the ignores that silenced nothing, and
// separately the reports another ignore silenced.
func (m *model) unusedIgnoreFindings() (out, quiet []*finding) {
	if m.rules.Unused == "off" || m.unseenTests && !m.testVariant {
		return nil, nil
	}
	var cands []*directive
	for _, f := range m.files {
		for _, d := range f.directives {
			if !d.effective || d.name != "ignore" || d.used {
				continue
			}
			if !d.bare && containsRule(d.rules, "overexported") {
				continue
			}
			if m.excludedNames(d) {
				continue
			}
			cands = append(cands, d)
		}
	}
	var pending []*finding
	for _, d := range cands {
		var msg string
		text := "//declscope:ignore"
		if !d.bare {
			text += " " + d.ruleText()
		}
		switch names := m.targetNames(d.target); {
		case d.fileLevel:
			msg = "unused file-level " + text
		case len(names) == 0:
			msg = "unused " + text + ": no checked declaration carries it"
		default:
			msg = "unused " + text + " on " + strings.Join(names, ", ")
		}
		}
		f := &finding{rule: "unused", pos: d.pos(), message: msg, dir: d, unusedOf: true}
		pending = append(pending, f)
	}
	silenced := make(map[*finding]bool)
	dropped := make(map[*finding]bool)
	for _, f := range pending {
		igs := m.covering(f)
		for _, ig := range igs {
			ig.used = true
		}
		if len(igs) > 0 {
			silenced[f] = true
			if !allFileLevel(igs) {
				dropped[f] = true
			}
		}
	}
	for _, f := range pending {
		if f.dir.used || dropped[f] {
			continue
		}
		if silenced[f] {
			quiet = append(quiet, f)
			continue
		}
		out = append(out, f)
	}
	m.sortByPos(out)
	return out, quiet
}

func allFileLevel(igs []*directive) bool {
	for _, ig := range igs {
		if !ig.fileLevel {
			return false
		}
	}
	return true
}

func containsRule(rules []string, r string) bool {
	for _, x := range rules {
		if x == r {
			return true
		}
	}
	return false
}

// targetNames names the declarations a target declares.
func (m *model) targetNames(t *target) []string {
	var names []string
	if t == nil {
		return nil
	}
	if t.kind == tBlock {
		for _, c := range t.children {
			for _, a := range c.anchors {
				names = append(names, a.display)
			}
		}
		return names
	}
	for _, a := range t.anchors {
		names = append(names, a.display)
	}
	return names
}

// excludedNames reports whether an ignore of boundary reaches a declaration
// that a build-excluded file names, so that the ignore may be in use there.
func (m *model) excludedNames(ig *directive) bool {
	if !ig.covers("boundary") || len(m.excluded) == 0 {
		return false
	}
	var names []string
	var collect func(t *target)
	collect = func(t *target) {
		for _, a := range t.anchors {
			names = append(names, a.name)
			if a.member && a.typeDecl != nil {
				names = append(names, a.typeDecl.name)
			}
		}
		for _, c := range t.children {
			collect(c)
		}
	}
	if ig.fileLevel {
		for _, t := range ig.file.targets {
			collect(t)
		}
	} else {
		collect(ig.target)
	}
	return mentions(m.excluded, names...)
}

// filterFinding reports a package read as empty because an only above the
// nearest one removes every file the nearest one matches.
func (m *model) filterFinding() *finding {
	only := m.rules.Only
	if len(only) == 0 {
		return nil
	}
	var paths []string
	var first *ast.File
	for _, f := range m.pass.Files {
		if ast.IsGenerated(f) {
			continue
		}
		if first == nil {
			first = f
		}
		paths = append(paths, m.fset.File(f.Pos()).Name())
	}
	// The nearest only matched files, and the rest of the filter took
	// every one of them back out.
	nearest := only[len(only)-1]
	matched := 0
	for _, p := range paths {
		if m.rules.admits(p) {
			return nil
		}
		if matchesList(nearest, p) {
			matched++
		}
	}
	if matched == 0 {
		return nil
	}
	return &finding{
		rule:    "filter",
		pos:     first.Package,
		message: fmt.Sprintf("filter.only stated in %s matches %d file(s) here, but an only above it removes them all, so this package is read as empty", nearest.Dir, matched),
	}
}

func matchesList(list PatternList, path string) bool {
	for _, p := range list.Patterns {
		if p.match(path) {
			return true
		}
	}
	return false
}
package analyzer

import (
	"path/filepath"
	"strings"
)

// Rules is the effective configuration for one package: every key resolved
// down the chain of config files.
type Rules struct {
	Unexported string // "shared" or "private"
	// UnexportedSet records whether a config file stated defaults.unexported.
	UnexportedSet bool
	Qualify       string // "always", "never" or "ondemand"
	Exported      bool
	Vocabulary    map[string][]string
	Boundary      bool
	Surplus       string // "off", "loose" or "strict"
	Unused        string // "off", "loose" or "strict"

	// Only holds one pattern list per stating file; a file must match every
	// list. Omit holds every omit pattern of the chain.
	Only []PatternList
	Omit []Pattern

	// Baseline is the path of the baseline to consult, or "".
	Baseline string
	// BaselineSet records whether a config file named the baseline.
	BaselineSet bool

	// Chain lists the config files read, outermost first.
	Chain []string
}

// PatternList is the filter.only list of one config file.
type PatternList struct {
	Dir      string
	Patterns []Pattern
}

// Pattern is a filter glob anchored at the directory of its config file.
type Pattern struct {
	Dir  string
	Text string
}

// DefaultRules returns the built-in defaults.
func DefaultRules() *Rules {
	return &Rules{
		Unexported: "private",
		Qualify:    "never",
		Boundary:   true,
		Surplus:    "strict",
		Unused:     "strict",
		Vocabulary: map[string][]string{},
	}
}

// FileSection is one parsed config file.
type FileSection struct {
	Path  string
	Shown string // the path as it was named
	Dir   string

	Unexported *string
	Qualify    *string
	Exported   *bool
	Vocabulary map[string][]string
	VocabOrder []string
	Boundary   *string
	Surplus    *string
	Unused     *string
	Only       []string
	OnlySet    bool
	Omit       []string
	Baseline   *string
}

// compose resolves a chain of config files, outermost first.
func compose(chain []*FileSection) *Rules {
	r := DefaultRules()
	for _, f := range chain {
		r.Chain = append(r.Chain, f.Shown)
		if f.Unexported != nil {
			r.Unexported = *f.Unexported
			r.UnexportedSet = true
		}
		if f.Qualify != nil {
			r.Qualify = *f.Qualify
		}
		if f.Exported != nil {
			r.Exported = *f.Exported
		}
		for ns, words := range f.Vocabulary {
			r.Vocabulary[ns] = words
		}
		if f.Boundary != nil {
			r.Boundary = *f.Boundary == "on"
		}
		if f.Surplus != nil {
			r.Surplus = *f.Surplus
		}
		if f.Unused != nil {
			r.Unused = *f.Unused
		}
		if len(f.Only) > 0 {
			list := PatternList{Dir: f.Dir}
			for _, p := range f.Only {
				list.Patterns = append(list.Patterns, Pattern{Dir: f.Dir, Text: p})
			}
			r.Only = append(r.Only, list)
		}
		for _, p := range f.Omit {
			r.Omit = append(r.Omit, Pattern{Dir: f.Dir, Text: p})
		}
		if f.Baseline != nil {
			r.Baseline = filepath.Join(f.Dir, *f.Baseline)
			r.BaselineSet = true
		}
	}
	return r
}

// match reports whether the file at path matches the pattern, which is read
// against the pattern's directory with .gitignore anchoring.
func (p Pattern) match(path string) bool {
	rel, err := filepath.Rel(p.Dir, path)
	if err != nil || rel == ".." || strings.HasPrefix(rel, "../") {
		return false
	}
	rel = filepath.ToSlash(rel)
	pat := p.Text
	dirOnly := strings.HasSuffix(pat, "/")
	pat = strings.TrimSuffix(pat, "/")
	anchored := false
	switch {
	case strings.HasPrefix(pat, "./"):
		pat = strings.TrimPrefix(pat, "./")
		anchored = true
	case strings.HasPrefix(pat, "/"):
		pat = strings.TrimPrefix(pat, "/")
		anchored = true
	case strings.Contains(pat, "/"):
		anchored = true
	}
	if dirOnly {
		pat += "/**"
	}
	if !anchored {
		pat = "**/" + pat
	}
	return globMatch(strings.Split(pat, "/"), strings.Split(rel, "/"))
}

// globMatch matches path segments against pattern segments. "**" matches
// any number of segments, though a trailing one needs at least one: a
// directory pattern names what is inside it.
func globMatch(pat, segs []string) bool {
	if len(pat) == 0 {
		return len(segs) == 0
	}
	if pat[0] == "**" {
		min := 0
		if len(pat) == 1 {
			min = 1
		}
		for i := min; i <= len(segs); i++ {
			if globMatch(pat[1:], segs[i:]) {
				return true
			}
		}
		return false
	}
	if len(segs) == 0 || !segMatch(pat[0], segs[0]) {
		return false
	}
	return globMatch(pat[1:], segs[1:])
}

// segMatch matches one path segment, where '*' matches any run of
// characters and '?' any one character.
func segMatch(pat, s string) bool {
	p, n := []rune(pat), []rune(s)
	var match func(i, j int) bool
	match = func(i, j int) bool {
		for i < len(p) {
			switch p[i] {
			case '*':
				for k := j; k <= len(n); k++ {
					if match(i+1, k) {
						return true
					}
				}
				return false
			case '?':
				if j >= len(n) {
					return false
				}
			default:
				if j >= len(n) || p[i] != n[j] {
					return false
				}
			}
			i++
			j++
		}
		return j == len(n)
	}
	return match(0, 0)
}

// admits reports whether the filter lets a file be read.
func (r *Rules) admits(path string) bool {
	for _, list := range r.Only {
		matched := false
		for _, p := range list.Patterns {
			if p.match(path) {
				matched = true
				break
			}
		}
		if !matched {
			return false
		}
	}
	for _, p := range r.Omit {
		if p.match(path) {
			return false
		}
	}
	return true
}

// Package checker is the command-line driver for the analyzer. It loads
// packages, runs the analyzer on each, and prints the diagnostics or applies
// their fixes, with the conventions of the go/analysis single checker.
package checker

import (
	"bytes"
	"cmp"
	"crypto/sha256"
	"encoding/json"
	"flag"
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"io"
	"log"
	"os"
	"runtime"
	"runtime/pprof"
	"runtime/trace"
	"slices"
	"sort"
	"strings"
	"time"

	"declscope/internal/load"
)

// TextEdit replaces the text between Pos and End with NewText.
type TextEdit struct {
	Pos, End token.Pos
	NewText  []byte
}

// SuggestedFix is a set of edits applied as a whole.
type SuggestedFix struct {
	Message   string
	TextEdits []TextEdit
}

// RelatedInformation is a secondary position of a diagnostic.
type RelatedInformation struct {
	Pos, End token.Pos
	Message  string
}

// Diagnostic is one report of the analyzer.
type Diagnostic struct {
	Pos, End       token.Pos
	Category       string
	Message        string
	SuggestedFixes []SuggestedFix
	Related        []RelatedInformation
}

// Pass is the input of one analyzer run on one package.
type Pass struct {
	Pkg       *load.Package
	Fset      *token.FileSet
	Files     []*ast.File
	Types     *types.Package
	TypesInfo *types.Info
	Report    func(Diagnostic)
}

// Analyzer describes the analysis the driver runs.
type Analyzer struct {
	Name  string
	Doc   string
	Flags *flag.FlagSet
	Run   func(*Pass) error
}

type action struct {
	pkg         *load.Package
	diagnostics []Diagnostic
	err         error
	duration    time.Duration
	inspect     time.Duration // the prerequisite AST inspection
}

// Options holds the driver's flag values.
type Options struct {
	IncludeTests bool
	Fix          bool
	Diff         bool
	JSON         bool
	Context      int
	Debug        string
	CPUProfile   string
	MemProfile   string
	Trace        string
}

func (opts *Options) dbg(b byte) bool { return strings.IndexByte(opts.Debug, b) >= 0 }

// Main parses the command line and runs the analyzer, then exits.
func Main(a *Analyzer) {
	log.SetFlags(0)
	log.SetPrefix(a.Name + ": ")

	var opts Options
	fs := flag.CommandLine
	fs.StringVar(&opts.Debug, "debug", "", `debug flags, any subset of "fpstv"`)
	fs.StringVar(&opts.CPUProfile, "cpuprofile", "", "write CPU profile to this file")
	fs.StringVar(&opts.MemProfile, "memprofile", "", "write memory profile to this file")
	fs.StringVar(&opts.Trace, "trace", "", "write trace log to this file")
	fs.BoolVar(&opts.IncludeTests, "test", true, "indicates whether test files should be analyzed, too")
	fs.BoolVar(&opts.Fix, "fix", false, "apply all suggested fixes")
	fs.BoolVar(&opts.Diff, "diff", false, "with -fix, don't update the files, but print a unified diff")

	fs.Usage = func() {
		paras := strings.Split(a.Doc, "\n\n")
		fmt.Fprintf(os.Stderr, "%s: %s\n\n", a.Name, paras[0])
		fmt.Fprintf(os.Stderr, "Usage: %s [-flag] [package]\n\n", a.Name)
		if len(paras) > 1 {
			fmt.Fprintln(os.Stderr, strings.Join(paras[1:], "\n\n"))
		}
		fmt.Fprintln(os.Stderr, "\nFlags:")
		fs.PrintDefaults()
	}

	if a.Flags != nil {
		a.Flags.VisitAll(func(f *flag.Flag) {
			if fs.Lookup(f.Name) != nil {
				log.Printf("%s flag -%s would conflict with driver; skipping", a.Name, f.Name)
				return
			}
			fs.Var(f.Value, f.Name, f.Usage)
		})
	}
	printflags := fs.Bool("flags", false, "print analyzer flags in JSON")
	fs.Var(versionFlag{}, "V", "print version and exit")
	fs.BoolVar(&opts.JSON, "json", false, "emit JSON output")
	fs.IntVar(&opts.Context, "c", -1, "display offending line with this many lines of context")
	_ = fs.Bool("source", false, "no effect (deprecated)")
	verbose := fs.Bool("v", false, "no effect (deprecated)")
	_ = fs.Bool("all", false, "no effect (deprecated)")
	_ = fs.String("tags", "", "no effect (deprecated)")

	flag.Parse()
	// -v is an undocumented alias for -debug=v.
	if *verbose && !strings.Contains(opts.Debug, "v") {
		opts.Debug += "v"
	}

	if *printflags {
		printFlags()
		os.Exit(0)
	}

	args := flag.Args()
	if len(args) == 0 {
		fs.Usage()
		os.Exit(1)
	}
	os.Exit(Run(args, a, &opts))
}

func printFlags() {
	type jsonFlag struct {
		Name  string
		Bool  bool
		Usage string
	}
	var flags []jsonFlag
	flag.VisitAll(func(f *flag.Flag) {
		switch f.Name {
		case "debug", "cpuprofile", "memprofile", "trace", "fix":
			return
		}
		b, ok := f.Value.(interface{ IsBoolFlag() bool })
		isBool := ok && b.IsBoolFlag()
		flags = append(flags, jsonFlag{f.Name, isBool, f.Usage})
	})
	data, err := json.MarshalIndent(flags, "", "\t")
	if err != nil {
		log.Fatal(err)
	}
	os.Stdout.Write(data)
}

type versionFlag struct{}

func (versionFlag) IsBoolFlag() bool { return true }
func (versionFlag) Get() any         { return nil }
func (versionFlag) String() string   { return "" }
func (versionFlag) Set(s string) error {
	if s != "full" {
		return fmt.Errorf("unsupported flag value: -V=%s (use -V=full)", s)
	}
	progname, err := os.Executable()
	if err != nil {
		return err
	}
	f, err := os.Open(progname)
	if err != nil {
		log.Fatal(err)
	}
	h := sha256.New()
	if _, err := io.Copy(h, f); err != nil {
		log.Fatal(err)
	}
	f.Close()
	fmt.Printf("%s version devel comments-go-here buildID=%02x\n", progname, string(h.Sum(nil)))
	os.Exit(0)
	return nil
}

// Run loads the packages named by args, analyzes them, and reports.
// It returns the exit code.
func Run(args []string, a *Analyzer, opts *Options) (exitcode int) {
	exitAtLeast := func(code int) { exitcode = max(code, exitcode) }

	if opts.CPUProfile != "" {
		f, err := os.Create(opts.CPUProfile)
		if err != nil {
			log.Fatal(err)
		}
		if err := pprof.StartCPUProfile(f); err != nil {
			log.Fatal(err)
		}
		defer pprof.StopCPUProfile()
	}
	if opts.Trace != "" {
		f, err := os.Create(opts.Trace)
		if err != nil {
			log.Fatal(err)
		}
		if err := trace.Start(f); err != nil {
			log.Fatal(err)
		}
		defer func() {
			trace.Stop()
			log.Printf("To view the trace, run:\n$ go tool trace view %s", opts.Trace)
		}()
	}
	if opts.MemProfile != "" {
		f, err := os.Create(opts.MemProfile)
		if err != nil {
			log.Fatal(err)
		}
		defer func() {
			runtime.GC()
			if err := pprof.WriteHeapProfile(f); err != nil {
				log.Fatalf("Writing memory profile: %v", err)
			}
			f.Close()
		}()
	}

	if opts.dbg('v') {
		log.SetPrefix("")
		log.SetFlags(log.Lmicroseconds)
		log.Printf("load %s", args)
	}
	initial, err := load.Load(&load.Config{Tests: opts.IncludeTests}, args...)
	if err == nil && len(initial) == 0 {
		err = fmt.Errorf("%s matched no packages", strings.Join(args, " "))
		err = fmt.Errorf("%s matched no packages", strings.Join(args, " "))
	}
	if err != nil {
		log.Print(err)
		return 1
	}
	if n := load.PrintErrors(os.Stderr, initial); n > 0 {
		exitAtLeast(1)
	}

	if opts.dbg('v') {
		log.Printf("building graph of analysis passes")
	}
	actions := make([]*action, len(initial))
	for i, pkg := range initial {
		act := &action{pkg: pkg}
		actions[i] = act
		start := time.Now()
		for _, f := range pkg.Syntax {
			ast.Inspect(f, func(ast.Node) bool { return true })
		}
		act.inspect = time.Since(start)
		start = time.Now()
		if pkg.IllTyped {
			act.err = fmt.Errorf("analysis skipped due to errors in package")
			act.duration = time.Since(start)
			continue
		}
		pass := &Pass{
			Pkg:       pkg,
			Fset:      pkg.Fset,
			Files:     pkg.Syntax,
			Types:     pkg.Types,
			TypesInfo: pkg.TypesInfo,
		}
		pass.Report = func(d Diagnostic) {
			for i := range d.SuggestedFixes {
				sortEdits(d.SuggestedFixes[i].TextEdits)
			}
			act.diagnostics = append(act.diagnostics, d)
		}
		act.err = a.Run(pass)
		act.duration = time.Since(start)
	}

	if opts.Fix {
		if err := applyFixes(actions, opts.Diff); err != nil {
			log.Print(err)
			exitAtLeast(1)
		}
		return
	}

	if opts.dbg('t') {
		defer printTiming(a.Name, actions, opts)
	}
	if opts.JSON {
		if err := printJSON(os.Stdout, a.Name, actions); err != nil {
			exitAtLeast(1)
		}
		return
	}
	printText(os.Stderr, a.Name, actions, opts.Context)
	var numErrors, rootDiags int
	for _, act := range actions {
		if act.err != nil {
			numErrors++
		} else {
			rootDiags += len(act.diagnostics)
		}
	}
	if numErrors > 0 {
		exitAtLeast(1)
	} else if rootDiags > 0 {
		exitAtLeast(3)
	}
	return
}

// printTiming prints the slowest actions, accounting for 90% of the total.
func printTiming(name string, actions []*action, opts *Options) {
	if !opts.dbg('p') {
		log.Println("Warning: times are mostly GC/scheduler noise; use -debug=tp to disable parallelism")
	}
	type timing struct {
		d    time.Duration
		name string
	}
	var list []timing
	var total time.Duration
	for _, act := range actions {
		list = append(list,
			timing{act.inspect, "inspect@" + act.pkg.ID},
			timing{act.duration, name + "@" + act.pkg.ID})
		total += act.inspect + act.duration
	}
	sort.Slice(list, func(i, j int) bool { return list[i].d > list[j].d })
	var sum time.Duration
	for _, t := range list {
		fmt.Fprintf(os.Stderr, "%s\t%s\n", t.d, t.name)
		sum += t.d
		if sum >= total*9/10 {
			break
		}
	}
	if total > sum {
		fmt.Fprintf(os.Stderr, "%s\tall others\n", total-sum)
	}
}

func sortEdits(edits []TextEdit) {
	slices.SortStableFunc(edits, func(x, y TextEdit) int {
		if sign := cmp.Compare(x.Pos, y.Pos); sign != 0 {
			return sign
		}
		return cmp.Compare(x.End, y.End)
	})
}

func printText(w io.Writer, name string, actions []*action, contextLines int) {
	type key struct {
		pos, end token.Position
		message  string
	}
	seen := make(map[key]bool)
	buf := new(bytes.Buffer)
	for _, act := range actions {
		if act.err != nil {
			fmt.Fprintf(w, "%s: %v\n", name, act.err)
			continue
		}
		fset := act.pkg.Fset
		for _, diag := range act.diagnostics {
			k := key{fset.Position(diag.Pos), fset.Position(diag.End), diag.Message}
			if seen[k] {
				continue
			}
			seen[k] = true
			printPlain(buf, fset, contextLines, diag)
		}
	}
	w.Write(buf.Bytes())
}

func printPlain(out io.Writer, fset *token.FileSet, contextLines int, diag Diagnostic) {
	print := func(pos, end token.Pos, message string) {
		posn := fset.Position(pos)
		fmt.Fprintf(out, "%s: %s\n", posn, message)
		if contextLines >= 0 {
			end := fset.Position(end)
			if !end.IsValid() {
				end = posn
			}
			data, _ := os.ReadFile(posn.Filename)
			lines := strings.Split(string(data), "\n")
			for i := posn.Line - contextLines; i <= end.Line+contextLines; i++ {
				if 1 <= i && i <= len(lines) {
					fmt.Fprintf(out, "%d\t%s\n", i, lines[i-1])
				}
			}
		}
	}
	print(diag.Pos, diag.End, diag.Message)
	for _, rel := range diag.Related {
		print(rel.Pos, rel.End, "\t"+rel.Message)
	}
}

type jsonTextEdit struct {
	Filename string `json:"filename"`
	Start    int    `json:"start"`
	End      int    `json:"end"`
	New      string `json:"new"`
}

type jsonSuggestedFix struct {
	Message string         `json:"message"`
	Edits   []jsonTextEdit `json:"edits"`
}

type jsonRelated struct {
	Posn    string `json:"posn"`
	End     string `json:"end"`
	Message string `json:"message"`
}

type jsonDiagnostic struct {
	Category       string             `json:"category,omitempty"`
	Posn           string             `json:"posn"`
	End            string             `json:"end"`
	Message        string             `json:"message"`
	SuggestedFixes []jsonSuggestedFix `json:"suggested_fixes,omitempty"`
	Related        []jsonRelated      `json:"related,omitempty"`
}

func printJSON(w io.Writer, name string, actions []*action) error {
	tree := make(map[string]map[string]any)
	for _, act := range actions {
		var v any
		fset := act.pkg.Fset
		if act.err != nil {
			type jsonError struct {
				Err string `json:"error"`
			}
			v = jsonError{act.err.Error()}
		} else if len(act.diagnostics) > 0 {
			diags := make([]jsonDiagnostic, 0, len(act.diagnostics))
			for _, d := range act.diagnostics {
