			for i := range d.SuggestedFixes {
				sortEdits(d.SuggestedFixes[i].TextEdits)
			}
			act.diagnostics = append(act.diagnostics, d)
		}
		act.err = a.Run(pass)
		act.duration = time.Since(start)
	}

