			stack = append(stack, lpkg)
			stubs := lpkg.Imports
			lpkg.Imports = make(map[string]*Package, len(stubs))
			paths := make([]string, 0, len(stubs))
			for p := range stubs {
				paths = append(paths, p)
			}
			sort.Strings(paths)
			for _, importPath := range paths {
				ipkg := stubs[importPath]
				var importErr error
				imp := ld.pkgs[ipkg.ID]
				if imp == nil {
