	"declscope/internal/checker"
	"declscope/internal/load"
)

const shrinkUsage = `Usage: declscope shrink [flags] [packages]

Reports the exported declarations of internal packages that nothing outside
their package uses, and with -fix unexports them.

Every package of the module is loaded, whatever the patterns name: an importer
outside them still counts. In a workspace, every module of it is loaded. The
patterns only choose which packages to report on, and default to ./... They
mean what they mean to the go command: a pattern it rejects stops the run, and
one that matches no package is warned about. Build tags come from GOFLAGS, as
for the analyzer.

A fix is offered only where no use can exist outside the package. Where a use
is possible but cannot be proved, such as a type that escapes into an
interface, the report stays and says why no fix is offered.

`

// isInternal reports whether an import path has an internal element.
func isInternal(path string) bool {
	for _, e := range strings.Split(path, "/") {
		if e == "internal" {
			return true
		}
	}
	return false
}

// shrinkCand is an exported declaration of a judged package.
type shrinkCand struct {
	obj    types.Object
	name   string
	kind   string
	ident  *ast.Ident
	key    string // baseline name: Type.member for members and methods
	ns     string
	file   *fileInfo
	doc    *ast.CommentGroup
	target *target
	typeOf *types.TypeName // the type of a field or method
	setOf  *types.TypeName // the type of a const set
	unit   *shrinkUnit
	member bool
	method bool
	isTest bool

	external bool // used outside the package
	xtest    bool // used by the external tests
	setKept  bool // another value of its const set keeps its name
	ignored  bool // an ignore of overexported, or the baseline, keeps its name
	reason   string
	fixable  bool
}

type shrinkUnit struct {
	path  string
	pkg   *load.Package
	model *model
	cands []*shrinkCand
	rules *Rules
	noFix string // why no declaration of the package can be fixed
	base  Baseline
}

// ShrinkMain runs "declscope shrink".
func ShrinkMain(args []string) int {
	fs := flag.NewFlagSet("declscope shrink", flag.ExitOnError)
	config := fs.String("config", "", "path to a declscope YAML config file, for the baseline it names")
	fix := fs.Bool("fix", false, "unexport every declaration a fix is offered for")
	fs.Usage = func() {
		fmt.Fprint(fs.Output(), shrinkUsage)
		fs.PrintDefaults()
	}
	fs.Parse(args)
	patterns := fs.Args()
	if len(patterns) == 0 {
		patterns = []string{"./..."}
	}
	res, err := runShrink(patterns, *config, "shrink", true)
	if err != nil {
		fmt.Fprintf(os.Stderr, "declscope shrink: %v\n", err)
		return 1
	}
	var lines []*shrinkFinding
	for _, f := range res.findings {
		lines = append(lines, f)
	}
	if *fix {
		var unfixed []*shrinkFinding
		var fixed []*shrinkFinding
		for _, f := range lines {
			if f.fix != nil {
				fixed = append(fixed, f)
			} else {
				unfixed = append(unfixed, f)
			}
		}
		if err := applyShrinkFixes(res.fset, fixed); err != nil {
			fmt.Fprintf(os.Stderr, "declscope shrink: %v\n", err)
			return 1
		}
		lines = unfixed
	}
	for _, f := range lines {
		fmt.Fprintf(os.Stdout, "%s: %s\n", res.fset.Position(f.pos), f.message)
	}
	if len(lines) > 0 {
		return 3
	}
	return 0
}

type shrinkFinding struct {
	pos     token.Pos
	message string
	fix     []checker.TextEdit
	cand    *shrinkCand
	unit    *shrinkUnit
	ns      string
	key     string
	ignored bool
}

type shrinkResult struct {
	fset     *token.FileSet
	findings []*shrinkFinding
	units    []*shrinkUnit
	all      []*shrinkFinding // every finding before ignores and baselines
	skipped  map[string]bool
}

// goModules lists the main modules of the go command run here.
func goModules() ([]load.Module, error) {
	cmd := exec.Command("go", "list", "-m", "-json")
	var out, errb bytes.Buffer
	cmd.Stdout, cmd.Stderr = &out, &errb
	if err := cmd.Run(); err != nil {
		return nil, fmt.Errorf("%s", strings.TrimSpace(errb.String()))
	}
	var mods []load.Module
	for dec := json.NewDecoder(&out); dec.More(); {
		var m load.Module
		if err := dec.Decode(&m); err != nil {
			return nil, err
		}
		mods = append(mods, m)
	}
	return mods, nil
}

// matched lists the packages the patterns select, and the patterns that
// select none.
func matchedPackages(patterns []string) (map[string]bool, []string, error) {
	args := append([]string{"list", "-e", "-json=ImportPath,Match,Error,DepOnly,Dir", "--"}, patterns...)
	cmd := exec.Command("go", args...)
	var out, errb bytes.Buffer
	cmd.Stdout, cmd.Stderr = &out, &errb
	if err := cmd.Run(); err != nil {
		return nil, nil, fmt.Errorf("err: %v: stderr: %s", err, errb.String())
	}
	sel := make(map[string]bool)
	used := make(map[string]bool)
	var rejected []string
	for dec := json.NewDecoder(&out); dec.More(); {
		var p struct {
			ImportPath string
			Dir        string
			Match      []string
			DepOnly    bool
			Error      *struct{ Err string }
		}
		if err := dec.Decode(&p); err != nil {
			return nil, nil, err
		}
		if p.DepOnly {
			continue
		}
		if p.Error != nil {
			// The go command rejects the pattern, or cannot read the
			// package it names.
			rejected = append(rejected, strings.TrimRight(p.Error.Err, "\n"))
			continue
		}
		sel[p.ImportPath] = true
		for _, m := range p.Match {
			used[m] = true
		}
	}
	if len(rejected) > 0 {
		sort.Strings(rejected)
		return nil, nil, fmt.Errorf("%s", strings.Join(rejected, "\n"))
	}
	var none []string
	for _, p := range patterns {
		if !used[p] {
			none = append(none, p)
		}
	}
	return sel, none, nil
}

// runShrink judges the internal packages the patterns select. A failure
// that stops the run is returned; what it judges, warns about and leaves out
// is printed under the name of the command.
func runShrink(patterns []string, configPath, cmdName string, warn bool) (*shrinkResult, error) {
	selected, none, err := matchedPackages(patterns)
	if err != nil {
		return nil, err
	}
	if len(selected) == 0 {
		return nil, fmt.Errorf("%s matched no packages", strings.Join(patterns, " "))
	}
	if warn {
		for _, p := range none {
			fmt.Fprintf(os.Stderr, "declscope %s: warning: %q matched no packages\n", cmdName, p)
		}
	}
	mods, err := goModules()
	if err != nil {
		return nil, err
	}
	var all []string
	for _, m := range mods {
		all = append(all, m.Dir+string(filepath.Separator)+"...")
	}
	pkgs, err := load.Load(&load.Config{Tests: true}, all...)
	if err != nil {
		return nil, err
	}
	us := units(pkgs)
	// Every variant with errors of its own is named, by its own first error.
	seenFail := make(map[string]bool)
	var failed []string
	for _, p := range pkgs {
		if isTestMain(p) || len(p.Errors) == 0 {
			continue
		}
		line := p.PkgPath + ": " + failureOf(p)
		if !seenFail[line] {
			seenFail[line] = true
			failed = append(failed, line)
		}
	}
	if len(failed) > 0 {
		sort.Strings(failed)
		return nil, fmt.Errorf("these packages do not type-check, so no absence of a use means anything:\n  %s", strings.Join(failed, "\n  "))
	}
	loaded := make(map[string]bool)
	for _, u := range us {
		loaded[u.path] = true
	}

	res := &shrinkResult{skipped: make(map[string]bool)}
	if len(pkgs) > 0 {
		res.fset = pkgs[0].Fset
	}
	// Choose the packages to judge.
	var notJudged []string
	var paths []string
	for p := range selected {
		paths = append(paths, p)
	}
	sort.Strings(paths)
	byPath := make(map[string]*unit)
	for _, u := range us {
		if !isXTest(u.pkg) {
			byPath[u.path] = u
		}
	}
	for _, path := range paths {
		if !isInternal(path) {
			continue
		}
		u := byPath[path]
		if u == nil {
			notJudged = append(notJudged, path+": ./... leaves it out, so this run does not load it")
			res.skipped[path] = true
			continue
		}
		if reason := skipReason(u.pkg); reason != "" {
			notJudged = append(notJudged, path+": "+reason)
			res.skipped[path] = true
			continue
		}
		rules, err := RulesFor(u.pkg, configPath)
		if err != nil {
			return nil, err
		}
		pass := &checker.Pass{Pkg: u.pkg, Fset: u.pkg.Fset, Files: u.pkg.Syntax, Types: u.pkg.Types, TypesInfo: u.pkg.TypesInfo}
		res.units = append(res.units, &shrinkUnit{path: path, pkg: u.pkg, model: newModel(pass, rules), rules: rules})
	}
	extra, more, err := moduleRanges(mods, res)
	if err != nil {
		return nil, err
	}
	notJudged = append(notJudged, more...)
	sort.Strings(notJudged)
	for _, s := range notJudged {
		fmt.Fprintf(os.Stderr, "declscope %s: not judged: %s\n", cmdName, s)
	}
	if res.fset == nil {
		return res, nil
	}
	// The baseline command regenerates the baseline, and never reads it.
	analyzeShrink(res, append(us, extra...), configPath, warn)
	return res, nil
}

// skipReason says why a package cannot be judged.
func skipReason(p *load.Package) string {
	if p.Name == "main" {
		return "package main"
	}
	if len(p.CgoFiles()) > 0 {
		return "the package uses cgo"
	}
	entries, err := os.ReadDir(p.Dir)
	if err == nil {
		for _, e := range entries {
			if e.IsDir() {
				continue
			}
			switch filepath.Ext(e.Name()) {
			case ".s", ".S", ".sx", ".c", ".cc", ".cpp", ".cxx", ".h", ".hh", ".hpp", ".hxx", ".m", ".f", ".F", ".for", ".f90", ".swig", ".swigcxx", ".syso":
				return "the package holds non-Go files"
			}
		}
	}
	return ""
}

// applyShrinkFixes writes the renames of the fixable findings.
func applyShrinkFixes(fset *token.FileSet, fs []*shrinkFinding) error {
	type edit struct {
		start, end int
		text       string
	}
	byFile := make(map[string][]edit)
	for _, f := range fs {
		for _, e := range f.fix {
			tf := fset.File(e.Pos)
			byFile[tf.Name()] = append(byFile[tf.Name()], edit{tf.Offset(e.Pos), tf.Offset(e.End), string(e.NewText)})
		}
	}
	var files []string
	for name := range byFile {
		files = append(files, name)
	}
	sort.Strings(files)
	for _, name := range files {
		src, err := os.ReadFile(name)
		if err != nil {
			return err
		}
		edits := byFile[name]
		sort.SliceStable(edits, func(i, j int) bool { return edits[i].start < edits[j].start })
		var out bytes.Buffer
		last := 0
		for _, e := range edits {
			if e.start < last {
				continue
			}
			out.Write(src[last:e.start])
			out.WriteString(e.text)
			last = e.end
		}
		out.Write(src[last:])
		if err := os.WriteFile(name, out.Bytes(), 0644); err != nil {
			return err
		}
	}
	return nil
}

var (
	_ = ast.IsExported
	_ = parser.ParseFile
	_ = unicode.IsUpper
	_ = types.Universe
)
package analyzer

import (
	"bytes"
	"encoding/json"
	"fmt"
	"go/parser"
	"go/token"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strconv"
	"strings"

	"declscope/internal/load"
)

// internalParent returns the path of the tree that may import an internal
// package: the parent of its last internal element.
func internalParent(path string) string {
	elems := strings.Split(path, "/")
	for i := len(elems) - 1; i >= 0; i-- {
		if elems[i] == "internal" {
			return strings.Join(elems[:i], "/")
		}
	}
	return path
}

func inTree(path, parent string) bool {
	return parent == "" || path == parent || strings.HasPrefix(path, parent+"/")
}

// buildModule is one module of a build list.
type buildModule struct {
	Path  string
	Main  bool
	Dir   string
	Error *struct{ Err string }
}

// readBuildList reads the build list of the module or workspace the go
// command finds from dir. A failure is described as it follows "reading the
// build list failed: ".
func readBuildList(dir string) ([]buildModule, string) {
	cmd := exec.Command("go", "list", "-m", "-e", "-json", "all")
	cmd.Dir = dir
	var out, errb bytes.Buffer
	cmd.Stdout, cmd.Stderr = &out, &errb
	if err := cmd.Run(); err != nil {
		if strings.Contains(errb.String(), "can't compute 'all' using the vendor directory") {
			return vendoredBuildList(dir)
		}
		return nil, strings.TrimSpace(errb.String())
	}
	var mods []buildModule
	for dec := json.NewDecoder(&out); dec.More(); {
		var m buildModule
		if err := dec.Decode(&m); err != nil {
			return mods, err.Error()
		}
		mods = append(mods, m)
	}
	for _, m := range mods {
		if m.Error != nil {
			return mods, m.Path + ": " + strings.TrimSpace(m.Error.Err)
		}
	}
	return mods, ""
}

// vendoredBuildList reads the build list of a module built in vendor mode
// from vendor/modules.txt: each module is read from its vendored copy.
func vendoredBuildList(dir string) ([]buildModule, string) {
	cmd := exec.Command("go", "list", "-m", "-json")
	cmd.Dir = dir
	var out, errb bytes.Buffer
	cmd.Stdout, cmd.Stderr = &out, &errb
	if err := cmd.Run(); err != nil {
		return nil, strings.TrimSpace(errb.String())
	}
	var mods []buildModule
	root := dir
	for dec := json.NewDecoder(&out); dec.More(); {
		var m buildModule
		if err := dec.Decode(&m); err != nil {
			return nil, err.Error()
		}
		mods = append(mods, m)
		if m.Dir != "" {
			root = m.Dir
		}
	}
	data, err := os.ReadFile(filepath.Join(root, "vendor", "modules.txt"))
	if err != nil {
		return nil, err.Error()
	}
	var vendored []buildModule
	for _, line := range strings.Split(string(data), "\n") {
		rest, ok := strings.CutPrefix(line, "# ")
		if !ok {
			continue
		}
		f := strings.Fields(rest)
		if len(f) == 0 {
			continue
		}
		vendored = append(vendored, buildModule{Path: f[0], Dir: filepath.Join(root, "vendor", filepath.FromSlash(f[0]))})
	}
	sort.SliceStable(vendored, func(i, j int) bool { return vendored[i].Path < vendored[j].Path })
	return append(mods, vendored...), ""
}

// modulePath returns the module path a go.mod file declares, tolerating
// unrelated problems in it, or "" if it declares none.
func modulePath(data []byte) string {
	for len(data) > 0 {
		line := data
		data = nil
		if i := bytes.IndexByte(line, '\n'); i >= 0 {
			line, data = line[:i], line[i+1:]
		}
		if i := bytes.Index(line, []byte("//")); i >= 0 {
			line = line[:i]
		}
		line = bytes.TrimSpace(line)
		rest, ok := bytes.CutPrefix(line, []byte("module"))
		if !ok {
			continue
		}
		n := len(rest)
		rest = bytes.TrimSpace(rest)
		if len(rest) == n || len(rest) == 0 {
			continue
		}
		if rest[0] == '"' || rest[0] == '`' {
			p, err := strconv.Unquote(string(rest))
			if err != nil {
				return ""
			}
			return p
		}
		return string(rest)
	}
	return ""
}

type nestedModule struct {
	path, dir string
}

// findNested lists the modules below a module root.
func findNested(root string) ([]nestedModule, error) {
	var out []nestedModule
	var failed error
	filepath.WalkDir(root, func(path string, d os.DirEntry, err error) error {
		if err != nil || !d.IsDir() || path == root {
			return nil
		}
		if d.Name() == ".git" {
			return filepath.SkipDir
		}
		gomod := filepath.Join(path, "go.mod")
		data, err := os.ReadFile(gomod)
		if err != nil {
			return nil
		}
		mp := modulePath(data)
		if mp == "" {
			failed = fmt.Errorf("reading %s: no module path", gomod)
			return filepath.SkipAll
		}
		out = append(out, nestedModule{path: mp, dir: path})
		return nil
	})
	return out, failed
}

// moduleImports lists, sorted, the import paths the Go files of a module
// copy name, whatever their build constraints.
func moduleImports(root string) []string {
	seen := make(map[string]bool)
	var out []string
	filepath.WalkDir(root, func(path string, d os.DirEntry, err error) error {
		if err != nil {
			return nil
		}
		if d.IsDir() {
			if path == root {
				return nil
			}
			if d.Name() == "vendor" {
				return filepath.SkipDir
			}
			if _, err := os.Stat(filepath.Join(path, "go.mod")); err == nil {
				return filepath.SkipDir
			}
			return nil
		}
		if !strings.HasSuffix(d.Name(), ".go") {
			return nil
		}
		f, _ := parser.ParseFile(token.NewFileSet(), path, nil, parser.ImportsOnly)
		if f == nil {
			return nil
		}
		for _, is := range f.Imports {
			if p, err := strconv.Unquote(is.Path.Value); err == nil && !seen[p] {
				seen[p] = true
				out = append(out, p)
			}
		}
		return nil
	})
	sort.Strings(out)
	return out
}

// moduleRanges judges what the modules around the main ones mean for the
// judged packages. Nested modules that may import a package and read it from
// other source, or fail to load, take it out of judgement; so does a module
// of the build list that may hold an importer. A module that a nested module
// builds from outside the tree and that imports an internal package withholds
// the fixes of its range. It returns the packages of the nested modules,
// whose uses count, and the packages it takes out of judgement, with the
// reason.
func moduleRanges(mods []load.Module, res *shrinkResult) ([]*unit, []string, error) {
	loaded := make(map[string]bool)
	for _, m := range mods {
		loaded[filepath.Clean(m.Dir)] = true
	}
	var nested []nestedModule
	for _, root := range mods {
		ns, err := findNested(root.Dir)
		if err != nil {
			return nil, nil, err
		}
		nested = append(nested, ns...)
	}
	for _, nm := range nested {
		loaded[filepath.Clean(nm.dir)] = true
	}

	var extra []*unit
	var notJudged []string
	drop := func(su *shrinkUnit, reason string) {
		notJudged = append(notJudged, su.path+": "+reason)
		res.skipped[su.path] = true
	}
	judged := func() []*shrinkUnit {
		var out []*shrinkUnit
		for _, su := range res.units {
			if !res.skipped[su.path] {
				out = append(out, su)
			}
		}
		return out
	}

	imports := make(map[string][]string)
	for _, nm := range nested {
		var inRange []*shrinkUnit
		for _, su := range judged() {
			if inTree(nm.path, internalParent(su.path)) {
				inRange = append(inRange, su)
			}
		}
		if len(inRange) > 0 {
			pkgs, err := load.Load(&load.Config{Dir: nm.dir, Tests: true}, "./...")
			for _, su := range inRange {
				if reason := nestedFailure(pkgs, err, su); reason != "" {
					drop(su, fmt.Sprintf("the nested module %s may import it, and %s", nm.path, reason))
				}
			}
			if err == nil {
				extra = append(extra, units(pkgs)...)
			}
		}

		list, failure := readBuildList(nm.dir)
		for _, su := range judged() {
			if su.noFix != "" {
				continue
			}
			parent := internalParent(su.path)
			if failure != "" && inTree(nm.path, parent) {
				su.noFix = fmt.Sprintf("the build list of the nested module %s cannot be read, and a module it names may use it: reading the build list failed: %s", nm.path, failure)
				continue
			}
			for _, m := range list {
				if m.Main || m.Dir == "" || loaded[filepath.Clean(m.Dir)] {
					continue
				}
				imps, ok := imports[m.Dir]
				if !ok {
					imps = moduleImports(m.Dir)
					imports[m.Dir] = imps
				}
				if q := internalImport(imps, parent); q != "" {
					su.noFix = fmt.Sprintf("the build of the nested module %s uses %s from %s, which imports %s", nm.path, m.Path, m.Dir, q)
					break
				}
			}
		}
	}

	if units := judged(); len(units) > 0 {
		list, failure := readBuildList(".")
		for _, su := range units {
			if failure != "" {
				drop(su, "reading the build list failed: "+failure)
				continue
			}
			parent := internalParent(su.path)
			for _, m := range list {
				if m.Main || loaded[filepath.Clean(m.Dir)] {
					continue
				}
				if holds(m, parent) {
					drop(su, fmt.Sprintf("the build uses %s from %s", m.Path, m.Dir))
					break
				}
			}
		}
	}
	res.units = judged()
	return extra, notJudged, nil
}

// nestedFailure says why the load of a nested module leaves a package
// unjudged, or returns "".
func nestedFailure(pkgs []*load.Package, err error, su *shrinkUnit) string {
	if err != nil {
		return "loading it failed: " + err.Error()
	}
	var listed []string
	reads := false
	var from string
	load.Visit(pkgs, nil, func(p *load.Package) {
		for _, e := range p.Errors {
			// A compile error the go command met building export data is
			// a type error, not a failure to load.
			if e.Kind == load.ListError && !strings.HasPrefix(e.Msg, "# ") {
				listed = append(listed, p.PkgPath+": "+describeError(e))
				break
			}
		}
		if p.PkgPath == su.path && !reads {
			reads = true
			if p.Dir != su.pkg.Dir {
				from = p.Dir
				if p.Module != nil && p.Module.Dir != "" {
					from = p.Module.Dir
				}
			}
		}
	})
	if len(listed) > 0 {
		sort.Strings(listed)
		return "loading it failed: " + listed[0]
	}
	if !reads {
		return ""
	}
	var broken []string
	for _, p := range pkgs {
		if isTestMain(p) || len(p.Errors) == 0 {
			continue
		}
		broken = append(broken, fmt.Sprintf("its package %s does not type-check: %s", p.PkgPath, describeError(firstError(p))))
	}
	if len(broken) > 0 {
		sort.Strings(broken)
		return broken[0]
	}
	if from != "" {
		return fmt.Sprintf("it reads %s from %s", su.path, from)
	}
	return ""
}

// internalImport returns the first of the sorted import paths that names an
// internal package in the tree of parent, or "".
func internalImport(imps []string, parent string) string {
	for _, imp := range imps {
		if isInternal(imp) && inTree(imp, parent) {
			return imp
		}
	}
	return ""
}

// holds reports whether a module of the build list may hold a package in the
// tree of parent: its path lies in the tree, or above it with the tree's
// directory inside.
func holds(m buildModule, parent string) bool {
	if inTree(m.Path, parent) {
		return true
	}
	rel, ok := strings.CutPrefix(parent, m.Path+"/")
	if !ok || m.Dir == "" {
		return false
	}
	fi, err := os.Stat(filepath.Join(m.Dir, filepath.FromSlash(rel)))
	return err == nil && fi.IsDir()
}

package analyzer

import (
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"unicode"

	"declscope/internal/checker"
	"declscope/internal/load"
	"declscope/internal/yaml"
)

const baselineUsage = `Usage: declscope baseline [flags] [packages]

Records every current violation so that adopting declscope does not require
fixing them all at once. New violations are still reported.

Each package's entries go to the baseline the analyzer will consult for that
package: the one named by its nearest config file, else the nearest existing
default-named baseline at or below the working directory, else
.declscope-baseline.yaml in the working directory. Every file written is
regenerated wholesale; baselines above the working directory are left alone.

Wholesale means a narrower pattern drops the entries of every package it does
not load from the files it writes. -merge keeps them: it reads each file first,
replaces the entries of the packages this run loaded and keeps the rest. A file
-merge cannot parse stops the run.

What declscope shrink reports is recorded too, into the same files, so that
shrink passes on what the baseline already holds. That loads the whole module
once more. -shrink=false skips it, for a module that does not run shrink.

`

const baselineHeader = `# declscope baseline
#
# Violations recorded here are suppressed; new ones are still reported.
# Regenerate with:
#
#     declscope baseline ./...
#
# Do not edit by hand. An entry disappears when its violation is fixed, so the
# diff of a regeneration is the record of what was cleaned up.
`

// BaselineMain runs "declscope baseline".
func BaselineMain(args []string) int {
	fs := flag.NewFlagSet("declscope baseline", flag.ExitOnError)
	config := fs.String("config", "", "path to a declscope YAML config file")
	merge := fs.Bool("merge", false, "keep the entries of packages these patterns do not load")
	out := fs.String("o", "", "write every entry to this one file instead")
	withShrink := fs.Bool("shrink", true, "also record what declscope shrink reports (-shrink=false skips it)")
	fs.Usage = func() {
		fmt.Fprint(fs.Output(), baselineUsage)
		fs.PrintDefaults()
	}
	fs.Parse(args)
	patterns := fs.Args()
	if len(patterns) == 0 {
		patterns = []string{"./..."}
	}
	fail := func(format string, a ...any) int {
		fmt.Fprintf(os.Stderr, "declscope baseline: "+format+"\n", a...)
		return 1
	}

	pkgs, err := load.Load(&load.Config{Tests: true}, patterns...)
	if err != nil {
		return fail("%v", err)
	}
	if n := load.PrintErrors(os.Stderr, pkgs); n > 0 {
		return fail("packages contain errors")
	}
	us := units(pkgs)
	if len(us) == 0 {
		return fail("%s matched no packages", strings.Join(patterns, " "))
	}
	if _, none, err := matchedPackages(patterns); err == nil {
		for _, p := range none {
			fmt.Fprintf(os.Stderr, "declscope baseline: warning: %q matched no packages\n", p)
		}
	}

	cwd, _ := os.Getwd()
	entries := Baseline{}
	targets := make(map[string]string) // package path to file
	var unreachable []*unit
	for _, u := range us {
		rules, err := RulesFor(u.pkg, *config)
		if err != nil {
			return fail("%v", err)
		}
		target := *out
		if target == "" {
			var ok bool
			target, ok = baselineTarget(u.pkg, rules, cwd)
			if !ok {
				unreachable = append(unreachable, u)
				continue
			}
		}
		targets[u.path] = target
		res := Analyze(passFor(u.pkg), rules, nil)
		for _, f := range append(append([]*finding(nil), res.Findings...), res.Covered...) {
			if res.Ignored[f] || f.coveredBy != nil && len(res.Model.covering(f)) > 0 {
				continue
			}
			ns, name, ok := res.Model.baselineKey(f)
			if !ok {
				continue
			}
			entries.add(u.path, f.rule, ns, name)
		}
	}
	if len(unreachable) > 0 {
		fmt.Fprintf(os.Stderr, "declscope baseline: %s in %s would not be found from these packages, because the lookup from them never reaches the working directory:\n", BaselineName, cwd)
		for _, u := range unreachable {
			fmt.Fprintf(os.Stderr, "  %s (%s)\n", u.path, u.pkg.Dir)
		}
		fmt.Fprintf(os.Stderr, "run from a directory their lookup passes through, name a baseline in a config file near them, or pass -o\n")
		return 1
	}

	skipped := make(map[string]bool)
	if *withShrink {
		res, err := runShrink(patterns, *config, "baseline", false)
		if err != nil {
			return fail("declscope shrink: %v (pass -shrink=false to record the analyzer's findings alone)", err)
		}
		skipped = res.skipped
		for _, f := range res.all {
			if f.ignored || f.cand == nil {
				continue
			}
			if _, ok := targets[f.unit.path]; !ok {
				continue
			}
			entries.add(f.unit.path, "overexported", f.ns, f.key)
		}
	}

	// Gather the entries of each file.
	files := make(map[string]Baseline)
	for _, t := range targets {
		if files[t] == nil {
			files[t] = Baseline{}
		}
	}
	for pkg, rules := range entries {
		files[targets[pkg]][pkg] = rules
	}
	var names []string
	for name := range files {
		names = append(names, name)
	}
	sort.Strings(names)
	if *merge {
		for _, name := range names {
			old, err := readForMerge(name)
			if err != nil {
				return fail("%s cannot be parsed: %v; run without -merge to replace it", name, err)
			}
			for pkg, rules := range old {
				if _, loaded := targets[pkg]; !loaded {
					files[name][pkg] = rules
					continue
				}
				// A loaded package keeps shrink's entries when this run
				// recorded none for it.
				if oe := rules["overexported"]; oe != nil && (!*withShrink || skipped[pkg]) {
					if files[name][pkg] == nil {
						files[name][pkg] = map[string]map[string][]string{}
					}
					files[name][pkg]["overexported"] = oe
				}
			}
		}
	}
	for _, name := range names {
		b := files[name]
		if err := os.MkdirAll(filepath.Dir(name), 0o755); err != nil {
			return fail("%v", err)
		}
		if err := os.WriteFile(name, []byte(baselineHeader+encodeBaseline(b)), 0644); err != nil {
			return fail("%v", err)
		}
		fmt.Fprintf(os.Stderr, "declscope: recorded %d violation(s) in %s\n", b.Count(), name)
	}
	return 0
}

func readForMerge(path string) (Baseline, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return Baseline{}, nil
		}
		return nil, err
	}
	return ParseBaseline(data)
}

func (b Baseline) add(pkg, rule, ns, name string) {
	if b[pkg] == nil {
		b[pkg] = map[string]map[string][]string{}
	}
	if b[pkg][rule] == nil {
		b[pkg][rule] = map[string][]string{}
	}
	for _, n := range b[pkg][rule][ns] {
		if n == name {
			return
		}
	}
	b[pkg][rule][ns] = append(b[pkg][rule][ns], name)
}

// baselineTarget finds the file a package's entries go to.
func baselineTarget(pkg *load.Package, rules *Rules, cwd string) (string, bool) {
	if rules.BaselineSet {
		return rules.Baseline, true
	}
	for d := pkg.Dir; ; d = filepath.Dir(d) {
		rel, err := filepath.Rel(cwd, d)
		if err != nil || rel == ".." || strings.HasPrefix(rel, "../") {
			break
		}
		p := filepath.Join(d, BaselineName)
		if st, err := os.Stat(p); err == nil && !st.IsDir() {
			return p, true
		}
		if d == cwd || d == filepath.Dir(d) {
			return filepath.Join(cwd, BaselineName), true
		}
	}
	return "", false
}

func passFor(p *load.Package) *checker.Pass {
	return &checker.Pass{Pkg: p, Fset: p.Fset, Files: p.Syntax, Types: p.Types, TypesInfo: p.TypesInfo}
}

// encodeBaseline renders entries the way yaml.v3 marshals the map.
func encodeBaseline(b Baseline) string {
	if len(b) == 0 {
		return "packages: {}\n"
	}
	var sb strings.Builder
	sb.WriteString("packages:\n")
	for _, pkg := range yamlKeys(b) {
		sb.WriteString("  " + yamlScalar(pkg) + ":\n")
		rules := b[pkg]
		for _, rule := range yamlKeys(rules) {
			sb.WriteString("    " + yamlScalar(rule) + ":\n")
			nss := rules[rule]
			for _, ns := range yamlKeys(nss) {
				names := append([]string(nil), nss[ns]...)
				sort.Strings(names)
				if len(names) == 0 {
					sb.WriteString("      " + yamlScalar(ns) + ": []\n")
					continue
				}
				sb.WriteString("      " + yamlScalar(ns) + ":\n")
				for _, n := range names {
					sb.WriteString("        - " + yamlScalar(n) + "\n")
				}
			}
		}
	}
	return sb.String()
}

// yamlKeys sorts map keys the way yaml.v3 does: digit runs compare as
// numbers, letters before other characters only after digits.
func yamlKeys[V any](m map[string]V) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Slice(keys, func(i, j int) bool { return yamlKeyLess(keys[i], keys[j]) })
	return keys
}

func yamlKeyLess(a, b string) bool {
	ar, br := []rune(a), []rune(b)
	digits := false
	for i := 0; i < len(ar) && i < len(br); i++ {
		if ar[i] == br[i] {
			digits = unicode.IsDigit(ar[i])
			continue
		}
		al := unicode.IsLetter(ar[i])
		bl := unicode.IsLetter(br[i])
		if al && bl {
			return ar[i] < br[i]
		}
		if al || bl {
			if digits {
				return al
			}
			return bl
		}
		var ai, bi int
		var an, bn int64
		if ar[i] == '0' || br[i] == '0' {
			for j := i - 1; j >= 0 && unicode.IsDigit(ar[j]); j-- {
				if ar[j] != '0' {
					an = 1
					bn = 1
					break
				}
			}
		}
		for ai = i; ai < len(ar) && unicode.IsDigit(ar[ai]); ai++ {
			an = an*10 + int64(ar[ai]-'0')
		}
		for bi = i; bi < len(br) && unicode.IsDigit(br[bi]); bi++ {
			bn = bn*10 + int64(br[bi]-'0')
		}
		if an != bn {
			return an < bn
		}
		if ai != bi {
			return ai < bi
		}
		return ar[i] < br[i]
	}
	return len(ar) < len(br)
}

var base60 = regexp.MustCompile(`^[-+]?[0-9][0-9_]*(?::[0-5]?[0-9])+(?:\.[0-9_]*)?$`)

// yamlScalar renders a string as yaml.v3 does: plain when it reads back as
// the same string, double-quoted when it would resolve to another type,
// single-quoted when plain style is not allowed.
func yamlScalar(s string) string {
	switch s {
	case "y", "Y", "yes", "Yes", "YES", "on", "On", "ON",
		"n", "N", "no", "No", "NO", "off", "Off", "OFF":
		return fmt.Sprintf("%q", s)
	}
	if (&yaml.Node{Kind: yaml.ScalarNode, Value: s}).ShortTag() != "!!str" || base60.MatchString(s) {
		return fmt.Sprintf("%q", s)
	}
	if !plainAllowed(s) {
		return "'" + strings.ReplaceAll(s, "'", "''") + "'"
	}
	return s
}

// plainAllowed reports whether a block-context plain scalar may hold s.
func plainAllowed(s string) bool {
	if s == "" || strings.HasPrefix(s, "---") || strings.HasPrefix(s, "...") {
		return false
	}
	if s[0] == ' ' || s[len(s)-1] == ' ' {
		return false
	}
	for i, r := range s {
		follows := i+1 >= len(s) || s[i+1] == ' '
		if i == 0 {
			switch r {
			case '#', ',', '[', ']', '{', '}', '&', '*', '!', '|', '>', '\'', '"', '%', '@', '`':
				return false
			case '?', ':', '-':
				if follows {
					return false
				}
			}
			continue
		}
		switch r {
		case ':':
			if follows {
				return false
			}
		case '#':
			if s[i-1] == ' ' {
				return false
			}
		}
		if !unicode.IsPrint(r) {
			return false
		}
	}
	return true
}
package analyzer

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"sync"

	"declscope/internal/load"
	"declscope/internal/yaml"
)

// BaselineName is the default name of a baseline file.
const BaselineName = ".declscope-baseline.yaml"

// Baseline maps package path, rule and namespace to the declarations
// recorded there.
type Baseline map[string]map[string]map[string][]string

// Has reports whether an entry is recorded.
func (b Baseline) Has(pkg, rule, ns, name string) bool {
	for _, n := range b[pkg][rule][ns] {
		if n == name {
			return true
		}
	}
	return false
}

// Count returns the number of entries.
func (b Baseline) Count() int {
	n := 0
	for _, rules := range b {
		for _, nss := range rules {
			for _, names := range nss {
				n += len(names)
			}
		}
	}
	return n
}

var baselineCache = struct {
	sync.Mutex
	m map[string]*cachedBaseline
}{m: make(map[string]*cachedBaseline)}

type cachedBaseline struct {
	b   Baseline
	err error
}

// BaselinePath returns the baseline the analyzer consults for a package,
// or "" when there is none.
func BaselinePath(pkg *load.Package, rules *Rules) string {
	return baselineFrom(pkg, pkg.Dir, rules)
}

func baselineFrom(pkg *load.Package, dir string, rules *Rules) string {
	if rules.BaselineSet {
		return rules.Baseline
	}
	root := ""
	if pkg.Module != nil {
		root = pkg.Module.Dir
	}
	for d := dir; d != ""; d = filepath.Dir(d) {
		p := filepath.Join(d, BaselineName)
		if st, err := os.Stat(p); err == nil && !st.IsDir() {
			return p
		}
		if root == "" || d == root || d == filepath.Dir(d) {
			break
		}
		if rel, err := filepath.Rel(root, d); err != nil || strings.HasPrefix(rel, "..") {
			break
		}
	}
	return ""
}

// LoadBaseline reads a baseline file. A missing file is an empty baseline.
func LoadBaseline(path string) (Baseline, error) {
	baselineCache.Lock()
	defer baselineCache.Unlock()
	if c, ok := baselineCache.m[path]; ok {
		return c.b, c.err
	}
	b, err := ParseBaselineFile(path)
	if err != nil {
		err = fmt.Errorf("%s: %v (regenerate it with `declscope baseline ./...`)", path, err)
	}
	baselineCache.m[path] = &cachedBaseline{b, err}
	return b, err
}

// ParseBaselineFile reads a baseline file without caching.
func ParseBaselineFile(path string) (Baseline, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return Baseline{}, nil
		}
		return nil, err
	}
	return ParseBaseline(data)
}

// ParseBaseline decodes baseline content like yaml.v3 with known fields.
func ParseBaseline(data []byte) (Baseline, error) {
	doc, err := yaml.Parse(data)
	if err != nil {
		return nil, err
	}
	d := &decoder{}
	b := Baseline{}
	err = func() (err error) {
		defer func() {
			if r := recover(); r != nil {
				f, ok := r.(failure)
				if !ok {
					panic(r)
				}
				err = f.err
			}
		}()
		root := resolveNode(doc)
		if root == nil {
			return nil
		}
		d.structFields(root, "baseline.file", func(key string, _, v *yaml.Node) bool {
			if key != "packages" {
				return false
			}
			d.nestedMap(v, 3, func(keys []string, names []string) {
				pkg, rule, ns := keys[0], keys[1], keys[2]
				if b[pkg] == nil {
					b[pkg] = map[string]map[string][]string{}
				}
				if b[pkg][rule] == nil {
					b[pkg][rule] = map[string][]string{}
				}
				b[pkg][rule][ns] = names
			})
			return true
		})
		return nil
	}()
	if err != nil {
		return nil, err
	}
	if len(d.terrors) > 0 {
		return nil, errors.New("yaml: unmarshal errors:\n  " + strings.Join(d.terrors, "\n  "))
	}
	return b, nil
}

// nestedMap decodes depth levels of string-keyed maps ending in []string,
// calling leaf for every list.
func (d *decoder) nestedMap(n *yaml.Node, depth int, leaf func(keys, names []string)) {
	d.nestedMapKeys(n, depth, nil, leaf)
}

func mapTypeName(depth int) string {
	return strings.Repeat("map[string]", depth) + "[]string"
}

func (d *decoder) nestedMapKeys(n *yaml.Node, depth int, keys []string, leaf func(keys, names []string)) {
	n = resolveNode(n)
	if isNull(n) {
		return
	}
	switch n.Kind {
	case yaml.SequenceNode:
		d.terror(n, "!!seq", mapTypeName(depth))
		return
	case yaml.ScalarNode:
		checkExplicit(n)
		d.terror(n, n.ShortTag(), mapTypeName(depth))
		return
	}
	if d.dupKeys(n) {
		return
	}
	for i := 0; i+1 < len(n.Content); i += 2 {
		k, v := n.Content[i], n.Content[i+1]
		key, ok := d.str(k)
		if !ok && !isNull(resolveNode(k)) {
			continue
		}
		next := append(append([]string(nil), keys...), key)
		if depth == 1 {
			if names, ok := d.stringList(v); ok {
				leaf(next, names)
			}
			continue
		}
		d.nestedMapKeys(v, depth-1, next, leaf)
	}
}

// baselineKey returns the namespace and name under which a finding is
// recorded, if its rule is recorded at all.
func (m *model) baselineKey(f *finding) (string, string, bool) {
	switch f.rule {
	case "boundary", "qualify", "surplus":
	default:
		return "", "", false
	}
	d := f.decl
	if d == nil && f.dir != nil {
		if reach := m.reached(f.dir); len(reach) > 0 {
			d = reach[0]
		}
	}
	if d == nil {
		return "", "", false
	}
	return d.ns.key(), d.display, true
}

