	me := MeasurePackage(u.pkg, rules, base, basePath)
	if sc.format == "json" {
		writeInspectJSON(os.Stdout, me)
	} else {
		writeInspectMarkdown(os.Stdout, me)
	}
	return 0
}

func writeInspectJSON(w io.Writer, me *Measure) {
	type out struct {
		Package    string                `json:"package"`
		Config     []string              `json:"config"`
		AllCore    bool                  `json:"allCore"`
		Findings   map[string]*RuleCount `json:"findings"`
		Namespaces []*NamespaceInfo      `json:"namespaces"`
		Crossings  []*Crossing           `json:"crossings"`
		Edges      []*Edge               `json:"edges"`
		Names      []*NameInfo           `json:"names"`
	}
	o := out{
		Package:    me.Path,
		Config:     append([]string{}, me.Rules.Chain...),
		AllCore:    me.AllCore,
		Findings:   me.Counts,
		Namespaces: append([]*NamespaceInfo{}, me.Namespaces...),
		Crossings:  append([]*Crossing{}, me.Crossings...),
		Edges:      append([]*Edge{}, me.Edges...),
		Names:      append([]*NameInfo{}, me.Names...),
	}
	data, _ := json.MarshalIndent(o, "", "  ")
	fmt.Fprintf(w, "%s\n", data)
}

func writeInspectMarkdown(w io.Writer, me *Measure) {
	fmt.Fprintf(w, "# %s\n\n", me.Path)
	if len(me.Rules.Chain) > 0 {
		fmt.Fprintf(w, "Config: %s\n\n", chainText(me.Rules.Chain))
	}
	if me.NothingRead {
		fmt.Fprintf(w, "> No file of this package was read — every one is generated, or the filter removed them — so nothing here was checked.\n\n")
	}
	if me.AllCore {
		fmt.Fprintf(w, "> Every file is in the core namespace, so nothing crosses and no name is asked to carry one.\n\n")
	}

	fmt.Fprintf(w, "## Namespaces\n\n")
	var rows [][]string
	for _, n := range me.Namespaces {
		var files []string
		for _, f := range n.Files {
			files = append(files, "`"+f+"`")
		}
		rows = append(rows, []string{n.Namespace, strings.Join(files, ", "), fmt.Sprint(n.Declarations), num(me.QualifyAsked && !n.Core, n.QualifyTargets)})
	}
	writeTable(w, []column{{"namespace", false}, {"files", false}, {"declarations", true}, {"qualify targets", true}}, rows)
	fmt.Fprintln(w)

	fmt.Fprintf(w, "## Crossings\n\n")
	open := make(map[string]bool)
	for _, e := range me.Edges {
		if e.State == "open" {
			open[e.To+"\x00"+e.Declaration] = true
		}
	}
	if len(me.Crossings) == 0 && len(open) > 0 {
		fmt.Fprintf(w, "Open crossings only: %s shared by default rather than by decision, so there is nothing to put in the table or diagram.\n\n",
			plural(len(open), "declaration is", "declarations are"))
	} else if len(me.Crossings) == 0 {
		fmt.Fprintf(w, "Nothing crosses a namespace in this package.\n\n")
	} else {
		writeMermaid(w, me.Crossings)
		fmt.Fprintf(w, "<details>\n<summary>Table: %s</summary>\n\n", plural(len(me.Crossings), "crossing", "crossings"))
		b := me.BoundaryAsked
		rows = nil
		for _, c := range me.Crossings {
			mutual := ""
			if c.Mutual {
				mutual = "yes"
			}
			rows = append(rows, []string{
				c.From + " → " + c.To, mutual,
				num(b, c.Declared), num(b, c.Baselined), num(b, c.Reported), num(b, c.Clears),
				fmt.Sprintf("%d of %d", c.Reached, c.Declarations), fmt.Sprint(c.Uses),
			})
		}
		writeTable(w, []column{{"crossing", false}, {"mutual", false}, {"declared", true}, {"baselined", true}, {"reported", true}, {"clears", true}, {"reached", true}, {"uses", true}}, rows)
		fmt.Fprintf(w, "\n</details>\n\n")
	}
	if n := len(open); n > 0 && len(me.Crossings) > 0 {
		if n == 1 {
			fmt.Fprintf(w, "1 declaration is further: open, shared by default rather than by decision, so left out of the table and of the diagram.\n\n")
		} else {
			fmt.Fprintf(w, "%d declarations are further: open, shared by default rather than by decision, so left out of the table and of the diagram.\n\n", n)
		}
	}
	if len(me.Crossings) > 0 && me.BoundaryAsked {
		states := make(map[string]map[string]bool)
		for _, e := range me.Edges {
			if states[e.State] == nil {
				states[e.State] = make(map[string]bool)
			}
			states[e.State][e.To+"\x00"+e.Declaration] = true
		}
		fmt.Fprintf(w, "Declarations crossed: %d reported, %d baselined, %d declared. The columns above count within a pair, so they sum to more: a declaration reached from two namespaces is two rows and one finding.\n\n",
			len(states["reported"]), len(states["baselined"]), len(states["declared"]))
	}
	if len(me.Crossings) > 0 {
		writeMostReached(w, me)
	}

	fmt.Fprintf(w, "## Qualify\n\n")
	if !me.QualifyAsked {
		fmt.Fprintf(w, "Not asked: `rules.naming.qualify` does not apply to this package.\n\n")
		return
	}
	rows = nil
	for _, n := range me.Namespaces {
		if n.Core || n.QualifyTargets == 0 {
			rows = append(rows, []string{n.Namespace, "-", "-", "-", "-"})
			continue
		}
		rows = append(rows, []string{n.Namespace, fmt.Sprint(n.exempt), fmt.Sprint(n.baselined), fmt.Sprint(n.reported), fmt.Sprintf("%d of %d", n.failing, n.QualifyTargets)})
	}
	writeTable(w, []column{{"namespace", false}, {"exempt", true}, {"baselined", true}, {"reported", true}, {"saturation", true}}, rows)
	fmt.Fprintln(w)
}

// writeMermaid draws the crossings as a graph.
func writeMermaid(w io.Writer, cs []*Crossing) {
	fmt.Fprintf(w, "```mermaid\ngraph LR\n")
	ids := make(map[string]int)
	var nodes []string
	node := func(name string) {
		if _, ok := ids[name]; !ok {
			ids[name] = len(nodes)
			nodes = append(nodes, name)
		}
	}
	for _, c := range cs {
		node(c.From)
		node(c.To)
	}
	for i, n := range nodes {
		fmt.Fprintf(w, "  n%d[%q]\n", i, n)
	}
	for _, c := range cs {
		arrow := "-.->"
		switch {
		case c.Reported > 0:
			arrow = "==>"
		case c.Baselined > 0:
			arrow = "-->"
		}
		fmt.Fprintf(w, "  n%d %s|%d| n%d\n", ids[c.From], arrow, c.Reached, ids[c.To])
	}
	fmt.Fprintf(w, "```\n\n")
}

// writeMostReached ranks the declarations reached from other namespaces.
func writeMostReached(w io.Writer, me *Measure) {
	type row struct {
		decl, ns, state string
		from, uses      int
	}
	byDecl := make(map[string]*row)
	var rows []*row
	coreDecls := make(map[string]bool)
	for _, e := range me.Edges {
		if e.State == "open" {
			continue
		}
		key := e.To + "\x00" + e.Declaration
		if e.To == "(core)" {
			coreDecls[key] = true
			continue
		}
		r := byDecl[key]
		if r == nil {
			r = &row{decl: e.Declaration, ns: e.To, state: e.State}
			byDecl[key] = r
			rows = append(rows, r)
		}
		r.from++
		r.uses += e.Uses
	}
	sort.SliceStable(rows, func(i, j int) bool {
		a, b := rows[i], rows[j]
		if a.from != b.from {
			return a.from > b.from
		}
		if a.uses != b.uses {
			return a.uses > b.uses
		}
		if a.ns != b.ns {
			return a.ns < b.ns
		}
		return a.decl < b.decl
	})
	fmt.Fprintf(w, "## Most-reached declarations except `(core)`\n\n")
	if len(rows) > 10 {
		rows = rows[:10]
	}
	var cells [][]string
	for _, r := range rows {
		cells = append(cells, []string{"`" + r.decl + "`", r.ns, plural(r.from, "namespace", "namespaces"), r.state})
	}
	if len(cells) > 0 {
		writeTable(w, []column{{"declaration", false}, {"namespace", false}, {"reached from", false}, {"state", false}}, cells)
		fmt.Fprintln(w)
	}
	if n := len(coreDecls); n > 0 {
		if n == 1 {
			fmt.Fprintf(w, "1 declaration is further: the core's, which is the shared model and reached from everywhere by design.\n\n")
		} else {
			fmt.Fprintf(w, "%d declarations are further: the core's, which is the shared model and reached from everywhere by design.\n\n", n)
		}
	}
}
package analyzer

import (
	"flag"
	"fmt"
	"io"
	"os"
	"sort"
	"strings"
	"unicode/utf8"

	"declscope/internal/load"
)

// column describes one column of a markdown table.
type column struct {
	header  string
	numeric bool
}

// writeTable renders a markdown table with padded cells. A numeric column
// is right-aligned unless it holds nothing but dashes.
func writeTable(w io.Writer, cols []column, rows [][]string) {
	widths := make([]int, len(cols))
	right := make([]bool, len(cols))
	for i, c := range cols {
		widths[i] = utf8.RuneCountInString(c.header)
		for _, r := range rows {
			if n := utf8.RuneCountInString(r[i]); n > widths[i] {
				widths[i] = n
			}
			if c.numeric && r[i] != "-" {
				right[i] = true
			}
		}
	}
	pad := func(s string, i int) string {
		n := widths[i] - utf8.RuneCountInString(s)
		if right[i] {
			return strings.Repeat(" ", n) + s
		}
		return s + strings.Repeat(" ", n)
	}
	line := func(cells []string) {
		var b strings.Builder
		b.WriteString("|")
		for i, c := range cells {
			b.WriteString(" " + pad(c, i) + " |")
		}
		fmt.Fprintln(w, b.String())
	}
	headers := make([]string, len(cols))
	seps := make([]string, len(cols))
	for i, c := range cols {
		headers[i] = c.header
		if right[i] {
			seps[i] = strings.Repeat("-", widths[i]-1) + ":"
		} else {
			seps[i] = strings.Repeat("-", widths[i])
		}
	}
	line(headers)
	var b strings.Builder
	b.WriteString("|")
	for _, s := range seps {
		b.WriteString(" " + s + " |")
	}
	fmt.Fprintln(w, b.String())
	for _, r := range rows {
		line(r)
	}
}

// subcommand holds the flags shared by survey and inspect.
type subcommand struct {
	name        string
	fs          *flag.FlagSet
	config      string
	format      string
	test        bool
	allowErrors bool
}

func newSubcommand(name, usage string, allowErrors bool, configUsage string) *subcommand {
	sc := &subcommand{name: name}
	fs := flag.NewFlagSet("declscope "+name, flag.ExitOnError)
	if allowErrors {
		fs.BoolVar(&sc.allowErrors, "allow-errors", false, "measure anyway when some packages do not type-check")
	}
	fs.StringVar(&sc.config, "config", "", configUsage)
	fs.StringVar(&sc.format, "format", "markdown", "output format: markdown or json")
	fs.BoolVar(&sc.test, "test", true, "measure *_test.go files as well")
	fs.Usage = func() {
		fmt.Fprint(fs.Output(), usage)
		fs.PrintDefaults()
	}
	sc.fs = fs
	return sc
}

func (sc *subcommand) fail(format string, args ...any) int {
	fmt.Fprintf(os.Stderr, "declscope %s: %s\n", sc.name, fmt.Sprintf(format, args...))
	return 1
}

// unit is one measured package: a package merged with its in-package test
// variant, or an external test package.
type unit struct {
	path     string
	pkg      *load.Package   // the variant measured: the test variant if any
	variants []*load.Package // every variant, the plain package first
}

// illTyped reports whether some variant of the unit does not type-check.
func (u *unit) illTyped() bool {
	for _, v := range u.variants {
		if v.IllTyped {
			return true
		}
	}
	return false
}

// failure describes the first variant that does not type-check.
func (u *unit) failure() string {
	for _, v := range u.variants {
		if v.IllTyped {
			return failureOf(v)
		}
	}
	return ""
}

// isXTest reports whether p is an external test package.
func isXTest(p *load.Package) bool {
	return p.ForTest != "" && p.PkgPath != p.ForTest
}

// units selects the packages to measure from what the loader returned.
func units(pkgs []*load.Package) []*unit {
	byPath := make(map[string]*unit)
	var out []*unit
	for _, p := range pkgs {
		if isTestMain(p) {
			continue
		}
		u := byPath[p.PkgPath]
		if u == nil {
			u = &unit{path: p.PkgPath, pkg: p, variants: []*load.Package{p}}
			byPath[p.PkgPath] = u
			out = append(out, u)
			continue
		}
		if p.ForTest != "" {
			u.pkg = p
			u.variants = append(u.variants, p)
		} else {
			u.variants = append([]*load.Package{p}, u.variants...)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].path < out[j].path })
	return out
}

// isTestMain reports whether p is the generated main package of a test.
func isTestMain(p *load.Package) bool {
	return p.Name == "main" && strings.HasSuffix(p.ID, ".test") && p.ForTest == "" && !strings.Contains(p.ID, " ")
}

// failure describes why a package does not type-check.
func failureOf(p *load.Package) string {
	if len(p.Errors) > 0 {
		return describeError(firstError(p))
	}
	var dep *load.Package
	seen := make(map[*load.Package]bool)
	var find func(p *load.Package) bool
	find = func(p *load.Package) bool {
		paths := make([]string, 0, len(p.Imports))
		for path := range p.Imports {
			paths = append(paths, path)
		}
		sort.Strings(paths)
		for _, path := range paths {
			imp := p.Imports[path]
			if seen[imp] {
				continue
			}
			seen[imp] = true
			if !imp.IllTyped {
				continue
			}
			if len(imp.Errors) > 0 {
				dep = imp
				return true
			}
			if find(imp) {
				return true
			}
		}
		return false
	}
	if find(p) && dep != nil {
		return "imports " + dep.PkgPath + ": " + describeError(firstError(dep))
	}
	return "does not type-check"
}

func firstError(p *load.Package) load.Error {
	for _, e := range p.Errors {
		if e.Kind != load.ListError {
			return e
		}
	}
	// A dependency is checked without its function bodies; check it again
	// whole to find what it would report on its own.
	for _, e := range p.Errors {
		if e.Kind == load.ParseError {
			return e
		}
	}
	if errs := load.Recheck(p); len(errs) > 0 {
		return errs[0]
	}
	return p.Errors[0]
}

func describeError(e load.Error) string {
	msg := e.Msg
	if e.Pos != "" && e.Pos != "-" {
		msg = e.Pos + ": " + msg
	}
	return strings.ReplaceAll(msg, "\n", " ")
}

func plural(n int, one, many string) string {
	if n == 1 {
		return fmt.Sprintf("%d %s", n, one)
	}
	return fmt.Sprintf("%d %s", n, many)
}

func num(asked bool, n int) string {
	if !asked {
		return "-"
	}
	return fmt.Sprint(n)
}

// rulesText describes the rules in force.
func rulesText(r *Rules) string {
	parts := []string{}
	if r.Boundary {
		parts = append(parts, "boundary on")
	} else {
		parts = append(parts, "boundary off")
	}
	parts = append(parts, "qualify "+r.Qualify)
	if r.Exported {
		parts = append(parts, "exported")
	}
	parts = append(parts, "surplus "+r.Surplus, "unused "+r.Unused)
	return strings.Join(parts, ", ")
}

func chainText(chain []string) string {
	if len(chain) == 0 {
		return "built-in defaults"
	}
	var parts []string
	for _, c := range chain {
		parts = append(parts, "`"+c+"`")
	}
	return strings.Join(parts, " + ")
}
