			return
		}
		if d.isScope() && prev.isScope() {
			msg := fmt.Sprintf("conflicting scope directives: //declscope:%s and //declscope:%s", prev.name, d.name)
			if d.fileLevel {
				msg += " on one file"
			}
			m.problem(d, msg)
			return
		}
	}
	d.effective = true
	if d.fileLevel {
		f.fileDirs = append(f.fileDirs, d)
		switch {
		case d.isScope():
			f.scope = d
		case d.name == "ignore":
			f.ignores = append(f.ignores, d)
		}
		return
	}
	d.target.directives = append(d.target.directives, d)
	switch {
	case d.isScope():
		d.target.scope = d
	case d.name == "ignore":
		d.target.ignores = append(d.target.ignores, d)
	}
}

// assignNamespaces gives every file its namespace.
func (m *model) assignNamespaces() {
	coreStems := make(map[string]bool)
	explicit := make(map[*fileInfo]string)
	core := make(map[*fileInfo]bool)
	for _, f := range m.files {
		for _, d := range f.fileDirs {
			switch d.name {
			case "core":
				core[f] = true
			case "namespace":
				if _, ok := explicit[f]; !ok {
					explicit[f] = d.arg
				}
			}
		}
		if core[f] && !f.isTest {
			coreStems[strings.TrimSuffix(f.base, ".go")] = true
		}
	}
	for _, f := range m.files {
		var ns *namespace
		switch {
		case core[f]:
			ns = m.ns("", true)
		case explicit[f] != "":
			ns = m.ns(explicit[f], false)
		case f.isTest && coreStems[strings.TrimSuffix(f.base, "_test.go")]:
			ns = m.ns("", true)
		default:
			ns = m.ns(fileNamespace(f.base), false)
		}
		f.ns = ns
		ns.files = append(ns.files, f)
	}
}

func (m *model) ns(name string, core bool) *namespace {
	key := name
	if core {
		key = "(core)"
	}
	if ns, ok := m.namespaces[key]; ok {
		return ns
	}
	ns := &namespace{name: name, core: core}
	m.namespaces[key] = ns
	return ns
}

// collectDecls records the declarations the rules check.
func (m *model) collectDecls() {
	info := m.pass.TypesInfo
	add := func(id *ast.Ident, kind string, f *fileInfo, t *target) *decl {
		if id == nil || id.Name == "_" {
			return nil
		}
		obj := info.Defs[id]
		if obj == nil {
			return nil
		}
		d := &decl{
			obj:      obj,
			name:     id.Name,
			display:  id.Name,
			kind:     kind,
			ident:    id,
			file:     f,
			ns:       f.ns,
			target:   t,
			exported: ast.IsExported(id.Name),
		}
		m.decls = append(m.decls, d)
		m.byObj[obj] = d
		t.anchors = append(t.anchors, d)
		return d
	}
	var methods []*decl
	for _, f := range m.files {
		for _, t := range f.targets {
			switch t.kind {
			case tFunc:
				fd := t.node.(*ast.FuncDecl)
				if fd.Recv == nil {
					if fd.Name.Name == "init" {
						continue
					}
					add(fd.Name, "func", f, t)
					continue
				}
				if d := add(fd.Name, "method", f, t); d != nil {
					methods = append(methods, d)
				}
			case tGen, tBlock:
				gd := t.node.(*ast.GenDecl)
				for i, s := range gd.Specs {
				for i, s := range gd.Specs {
					st := t
					if t.kind == tBlock {
						st = t.children[i]
					}
					switch s := s.(type) {
					case *ast.ValueSpec:
						kind := "var"
						if gd.Tok == token.CONST {
							kind = "const"
						}
						for _, id := range s.Names {
							add(id, kind, f, st)
						}
					case *ast.TypeSpec:
						td := add(s.Name, "type", f, st)
						m.collectMembers(f, s, st, td)
					}
				}
			}
		}
	}
	for _, d := range methods {
		fn := d.obj.(*types.Func)
		recv := fn.Signature().Recv()
		if recv == nil {
			continue
		}
		rt := recv.Type()
		if p, ok := rt.(*types.Pointer); ok {
			rt = p.Elem()
		}
		if n, ok := types.Unalias(rt).(*types.Named); ok {
			tn := n.Origin().Obj()
			d.display = tn.Name() + "." + d.name
			d.typeDecl = m.byObj[tn]
		}
	}
	sort.SliceStable(m.decls, func(i, j int) bool {
		pi, pj := m.fset.Position(m.decls[i].ident.Pos()), m.fset.Position(m.decls[j].ident.Pos())
		if pi.Filename != pj.Filename {
			return pi.Filename < pj.Filename
		}
		return pi.Offset < pj.Offset
	})
}

// collectMembers records the fields or interface method names of a type.
func (m *model) collectMembers(f *fileInfo, s *ast.TypeSpec, st *target, td *decl) {
	var list *ast.FieldList
	kind := "field"
	switch t := s.Type.(type) {
	case *ast.StructType:
		list = t.Fields
	case *ast.InterfaceType:
		list = t.Methods
		kind = "method"
	}
	if list == nil {
		return
	}
	typeName := s.Name.Name
	i := 0
	for _, ft := range st.children {
		if ft.kind != tField {
			continue
		}
		field := list.List[i]
		i++
		ft.typeDecl = td
		for _, id := range field.Names {
			if id.Name == "_" {
				continue
			}
			obj := m.pass.TypesInfo.Defs[id]
			if obj == nil {
				continue
			}
			ns := f.ns
			d := &decl{
				obj:      obj,
				name:     id.Name,
				display:  typeName + "." + id.Name,
				kind:     kind,
				ident:    id,
				file:     f,
				ns:       ns,
				target:   ft,
				member:   true,
				typeDecl: td,
				exported: ast.IsExported(id.Name),
			}
			m.decls = append(m.decls, d)
			m.byObj[obj] = d
			ft.anchors = append(ft.anchors, d)
		}
	}
}

// fallback resolves the scope of d, ignoring the directives in skip.
func (m *model) scopeOf(d *decl, skip map[*directive]bool) (string, scopeSource) {
	if d == m.narrowed {
		return "private", scopeSource{kind: srcOwn}
	}
	live := func(x *directive) bool { return x != nil && !skip[x] && !m.deleted[x] }
	t := d.target
	if live(t.scope) {
		return t.scope.name, scopeSource{kind: srcOwn, dir: t.scope}
	}
	switch t.kind {
	case tSpec:
		if live(t.parent.scope) {
			return t.parent.scope.name, scopeSource{kind: srcBlock, dir: t.parent.scope}
		}
	case tField:
		tt := t.parent
		if live(tt.scope) {
			return tt.scope.name, scopeSource{kind: srcType, dir: tt.scope, typ: t.typeDecl}
		}
		if tt.kind == tSpec && live(tt.parent.scope) {
			return tt.parent.scope.name, scopeSource{kind: srcType, dir: tt.parent.scope, typ: t.typeDecl}
		}
	}
	if live(d.file.scope) {
		return d.file.scope.name, scopeSource{kind: srcFile, dir: d.file.scope}
	}
	if d.exported {
		return "shared", scopeSource{kind: srcExported}
	}
	return m.rules.Unexported, scopeSource{kind: srcDefault}
}

// ownScope returns the scope directive written on t itself, if any.
func (m *model) ownScope(t *target) *directive {
	if t.scope == nil || m.deleted[t.scope] {
		return nil
	}
	return t.scope
}

func (m *model) resolveScopes(skip map[*directive]bool) {
	m.deleted = skip
	m.reachCache = nil
	for _, d := range m.decls {
		d.scope, d.source = m.scopeOf(d, skip)
	}
}

// collectUses records, for every checked declaration, the places that name
// it in the analyzed files, in file order. An element of a struct literal
// written by position uses the field it fills.
func (m *model) collectUses() {
	info := m.pass.TypesInfo
	for _, f := range m.files {
		ast.Inspect(f.ast, func(n ast.Node) bool {
			switch n := n.(type) {
			case *ast.Ident:
				obj := info.Uses[n]
				if obj == nil {
					return true
				}
				if d := m.byObj[origin(obj)]; d != nil {
					d.uses = append(d.uses, use{pos: n.Pos(), end: n.End(), ident: n, file: f})
				}
			case *ast.CompositeLit:
				if len(n.Elts) == 0 {
					return true
				}
				if _, keyed := n.Elts[0].(*ast.KeyValueExpr); keyed {
					return true
				}
				st := literalStruct(info.TypeOf(n))
				if st == nil {
					return true
				}
				for i, e := range n.Elts {
					if i >= st.NumFields() {
						break
					}
					if d := m.byObj[origin(st.Field(i))]; d != nil {
						d.uses = append(d.uses, use{pos: e.Pos(), end: e.End(), file: f})
					}
				}
			}
			return true
		})
	}
}

// literalStruct returns the struct type a composite literal fills, when the
// literal names it: a struct type, or a type parameter whose constraint
// names exactly one struct.
func literalStruct(t types.Type) *types.Struct {
	if t == nil {
		return nil
	}
	if tp, ok := t.(*types.TypeParam); ok {
		iface, _ := tp.Constraint().Underlying().(*types.Interface)
		if iface == nil || iface.NumEmbeddeds() != 1 {
			return nil
		}
		et := iface.EmbeddedType(0)
		if u, ok := et.(*types.Union); ok {
			if u.Len() != 1 {
				return nil
			}
			et = u.Term(0).Type()
		}
		if p, ok := et.(*types.Pointer); ok {
			et = p.Elem()
		}
		if _, named := types.Unalias(et).(*types.Named); !named {
			return nil
		}
		st, _ := et.Underlying().(*types.Struct)
		return st
	}
	if p, ok := t.Underlying().(*types.Pointer); ok {
		t = p.Elem()
	}
	st, _ := t.Underlying().(*types.Struct)
	return st
}

func origin(obj types.Object) types.Object {
	switch o := obj.(type) {
	case *types.Var:
		return o.Origin()
	case *types.Func:
		return o.Origin()
	}
	return obj
}

// crossing returns the uses of d from outside its namespace.
func (d *decl) crossing() []use {
	var out []use
	for _, u := range d.uses {
		if u.file.ns != d.ns {
			out = append(out, u)
		}
	}
	return out
}
// The third result is the baseline the config file names, resolved against
// the config file, or "" when it names none. Where a package's entries belong
// in that case is the caller's decision — see DefaultBaseline.
func ResolveForBaseline(dir, explicit string) (opts internal.Options, configPath, named string, err error) {
	opts, chain, err := resolve(dir, explicit)
	if len(chain) > 0 {
		configPath = chain[len(chain)-1]
	}
	named, opts.BaselinePath = opts.BaselinePath, ""
	return opts, configPath, named, err
}

func resolve(dir, explicit string) (internal.Options, []string, error) {
	opts := internal.DefaultOptions()

	// An explicit -config names one file and asks for it, so no chain is
	// built: the caller said which rules to use.
	chain := []string{explicit}
	if explicit == "" {
		chain = FindChain(dir)
	}
	// Outermost first, so a nearer file overrides the keys it states and
	// leaves the rest as the file above set them.
	for _, p := range chain {
		f, err := Load(p)
		if err != nil {
			return opts, chain, err
		}
		if err := f.Apply(&opts); err != nil {
			return opts, chain, fmt.Errorf("%s: %w", p, err)
		}
	}
	if err := opts.Compile(); err != nil {
		return opts, chain, err
	}
	return opts, chain, nil
}

// FindChain walks up from dir and returns every config file it passes,
// outermost first. The nearest file is last, so applying the slice in order
// leaves the nearest one's stated keys on top.
//
// The search stops at a module root, so a stray config file somewhere above
// the module cannot silently change its rules. Config files do compose, so a
// file above the module would reach into it, which is the one thing the
// module boundary is there to prevent.
//
//declscope:ignore overexported // config_test drives the lookup through it
func FindChain(dir string) []string {
	var found []string
	for d := range dirsUp(dir) {
		if path := firstFile(d, names); path != "" {
			found = append(found, path)
		}
	}
	slices.Reverse(found)
	return found
}

// FindBaseline walks up from dir looking for a default-named baseline file.
// Its presence is what enables suppression, so the name is fixed and the
// search stops at the module root, exactly like the config lookup.
//
//declscope:ignore overexported // config_test drives the lookup through it
func FindBaseline(dir string) string { return findUp(dir, baselineNames) }

// DefaultBaseline returns where the entries of a package in dir belong when no
// config file names a baseline: the nearest existing default-named file
// between the package and root, which is what the analyzer will consult, else
// a new file in root, the directory the regeneration was run from.
//
// The search walks the same path as FindBaseline but stops at root. A
// default-named file above root holds entries for packages the run never saw,
// and rewriting it wholesale would drop them; a new file in root shadows it
// for exactly the packages under root instead.
//
// It reports false when root is not on the path at all — the package lies
// outside root, or a module boundary intervenes — because a file written in
// root would never be found from dir, and a baseline whose presence is not
// enough is worse than none. An existing file found on the way is committed
// to only once the walk has confirmed root is below it: for a package outside
// root, the nearest file is above root, and rewriting it has the same cost as
// rewriting one above root for a package inside.
func DefaultBaseline(dir, root string) (string, bool) {
	found := ""
	for d := range dirsUp(dir) {
		if found == "" {
			found = firstFile(d, baselineNames)
		}
		if sameDir(d, root) {
			if found != "" {
				return found, true
			}
			return filepath.Join(root, baselineNames[0]), true
		}
	}
	return "", false
}

// Load reads and parses a config file.
//
//declscope:ignore overexported // config_test parses files through it
func Load(path string) (*File, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
		for d := dir; d != ""; {
			if !yield(d) || isFile(filepath.Join(d, "go.mod")) {
				return
			}
			parent := filepath.Dir(d)
			if parent == d {
				return
			}
			d = parent
		}
	}
}

// firstFile returns the first of names that is a file in dir, or "" when none
// is.
func firstFile(dir string, names []string) string {
	for _, name := range names {
		if path := filepath.Join(dir, name); isFile(path) {
			return path
		}
	}
	return ""
}

func isFile(path string) bool {
	st, err := os.Stat(path)
	return err == nil && !st.IsDir()
}

// sameDir compares two directories by identity rather than spelling, since
// the working directory and the paths go/packages reports can differ through
// a symlink and still be the same place.
func sameDir(a, b string) bool {
	if a == b {
		return true
	}
	sa, errA := os.Stat(a)
	sb, errB := os.Stat(b)
	return errA == nil && errB == nil && os.SameFile(sa, sb)
}

