func containsGoFile(s []string) bool {
	for _, f := range s {
		if strings.HasSuffix(f, ".go") {
			return true
		}
	}
	return false
}

func absJoin(dir string, fileses ...[]string) (res []string) {
	for _, files := range fileses {
		for _, file := range files {
			if !filepath.IsAbs(file) {
				file = filepath.Join(dir, file)
			}
			res = append(res, file)
		}
	}
	return res
}

func otherFiles(p *jsonPackage) [][]string {
	return [][]string{p.CFiles, p.CXXFiles, p.MFiles, p.HFiles, p.FFiles, p.SFiles, p.SwigFiles, p.SwigCXXFiles, p.SysoFiles}
}

func (state *golistState) createDriverResponse(words ...string) (*driverResponse, error) {
	goVersion, err := state.getGoVersion()
	if err != nil {
		return nil, err
	}
	buf, err := state.invokeList(state.listArgs(words, goVersion))
	if err != nil {
		return nil, err
	}

	seen := make(map[string]*jsonPackage)
	pkgs := make(map[string]*Package)
	additionalErrors := make(map[string][]Error)
	response := &driverResponse{GoVersion: goVersion}
	for dec := json.NewDecoder(buf); dec.More(); {
		p := new(jsonPackage)
		if err := dec.Decode(p); err != nil {
			return nil, fmt.Errorf("JSON decoding failed: %v", err)
		}
		if p.ImportPath == "" {
			if p.Error != nil {
				return nil, Error{Pos: p.Error.Pos, Msg: p.Error.Err}
			}
			return nil, fmt.Errorf("package missing import path: %+v", p)
		}
		if filepath.IsAbs(p.ImportPath) && p.Error != nil {
			if pkgPath, ok := state.getPkgPath(p.ImportPath); ok {
				p.ImportPath = pkgPath
			}
		}
		if old, found := seen[p.ImportPath]; found {
			if old.Error == nil && p.Error == nil {
				continue
			}
			if old.Error != nil {
				var errkind string
				if strings.Contains(old.Error.Err, "not an importable package") {
					errkind = "not an importable package"
				} else if strings.Contains(old.Error.Err, "use of internal package") && strings.Contains(old.Error.Err, "not allowed") {
					errkind = "use of internal package not allowed"
				}
				if errkind != "" {
					if len(old.Error.ImportStack) < 1 {
						return nil, fmt.Errorf(`internal error: go list gave a %q error with empty import stack`, errkind)
					}
					importingPkg := old.Error.ImportStack[len(old.Error.ImportStack)-1]
					if importingPkg == old.ImportPath {
						if len(old.Error.ImportStack) < 2 {
							return nil, fmt.Errorf(`internal error: go list gave a %q error with an import stack without importing package`, errkind)
						}
						importingPkg = old.Error.ImportStack[len(old.Error.ImportStack)-2]
					}
					additionalErrors[importingPkg] = append(additionalErrors[importingPkg], Error{
						Pos:  old.Error.Pos,
						Msg:  old.Error.Err,
						Kind: ListError,
					})
				}
			}
			if old.Error == nil {
				continue
			}
		}
		seen[p.ImportPath] = p

		pkg := &Package{
			Name:            p.Name,
			ID:              p.ImportPath,
			Dir:             p.Dir,
			GoFiles:         absJoin(p.Dir, p.GoFiles, p.CgoFiles),
			CompiledGoFiles: absJoin(p.Dir, p.CompiledGoFiles),
			OtherFiles:      absJoin(p.Dir, otherFiles(p)...),
			EmbedFiles:      absJoin(p.Dir, p.EmbedFiles),
			IgnoredFiles:    absJoin(p.Dir, p.IgnoredGoFiles, p.IgnoredOtherFiles),
			ForTest:         p.ForTest,
			Module:          p.Module,
			DepOnly:         p.DepOnly,
			Raw:             p,
		}
		if len(pkg.CompiledGoFiles) > 0 {
			out := pkg.CompiledGoFiles[:0]
			for _, f := range pkg.CompiledGoFiles {
				if ext := filepath.Ext(f); ext != ".go" && ext != "" {
					continue
				}
				out = append(out, f)
			}
			pkg.CompiledGoFiles = out
		}
		if i := strings.IndexByte(pkg.ID, ' '); i >= 0 {
			pkg.PkgPath = pkg.ID[:i]
		} else {
			pkg.PkgPath = pkg.ID
		}
		if pkg.PkgPath == "unsafe" {
			pkg.CompiledGoFiles = nil
		} else if len(pkg.CompiledGoFiles) == 0 {
			pkg.CompiledGoFiles = pkg.GoFiles
		}
		if p.Export != "" && !filepath.IsAbs(p.Export) {
			pkg.ExportFile = filepath.Join(p.Dir, p.Export)
		} else {
			pkg.ExportFile = p.Export
		}

		ids := make(map[string]bool)
		for _, id := range p.Imports {
			ids[id] = true
		}
		pkg.Imports = make(map[string]*Package)
		for path, id := range p.ImportMap {
			pkg.Imports[path] = &Package{ID: id}
			delete(ids, id)
		}
		for id := range ids {
			if id == "C" {
				continue
			}
			pkg.Imports[id] = &Package{ID: id}
		}
		if !p.DepOnly {
			response.Roots = append(response.Roots, pkg.ID)
		}

		if err := p.Error; err != nil && state.shouldAddFilenameFromError(p) {
			addFilenameFromPos := func(pos string) bool {
				split := strings.Split(pos, ":")
				if len(split) < 1 {
					return false
				}
				filename := strings.TrimSpace(split[0])
				if filename == "" {
					return false
				}
				if !filepath.IsAbs(filename) {
					filename = filepath.Join(state.dir(), filename)
				}
				info, _ := os.Stat(filename)
				if info == nil {
					return false
				}
				pkg.CompiledGoFiles = append(pkg.CompiledGoFiles, filename)
				pkg.GoFiles = append(pkg.GoFiles, filename)
				return true
			}
			found := addFilenameFromPos(err.Pos)
			if !found {
				addFilenameFromPos(err.Err)
			}
		}

		if p.Error != nil {
			msg := strings.TrimSpace(p.Error.Err)
			if msg == "import cycle not allowed" && len(p.Error.ImportStack) != 0 {
				msg += fmt.Sprintf(": import stack: %v", p.Error.ImportStack)
			}
			pkg.Errors = append(pkg.Errors, Error{
				Pos:  p.Error.Pos,
				Msg:  msg,
				Kind: ListError,
			})
		}
		pkgs[pkg.ID] = pkg
	}

	for id, errs := range additionalErrors {
		if p, ok := pkgs[id]; ok {
			p.Errors = append(p.Errors, errs...)
		}
	}
	for _, pkg := range pkgs {
		response.Packages = append(response.Packages, pkg)
	}
	sort.Slice(response.Packages, func(i, j int) bool { return response.Packages[i].ID < response.Packages[j].ID })
	return response, nil
}

func (state *golistState) dir() string {
	if state.cfg.Dir != "" {
		return state.cfg.Dir
	}
	wd, _ := os.Getwd()
	return wd
}

func (state *golistState) shouldAddFilenameFromError(p *jsonPackage) bool {
	if len(p.GoFiles) > 0 || len(p.CompiledGoFiles) > 0 {
		return false
	}
	return len(p.Error.ImportStack) == 0 || p.Error.ImportStack[len(p.Error.ImportStack)-1] == p.ImportPath
}

// getPkgPath finds the package path of a directory if it's relative to a
// root directory (the main module's).
func (state *golistState) getPkgPath(dir string) (string, bool) {
	stdout, _, _, err := state.invoke("list", "-m", "-json")
	if err != nil {
		return "", false
	}
	for dec := json.NewDecoder(stdout); dec.More(); {
		var m Module
		if dec.Decode(&m) != nil {
			return "", false
		}
		if m.Dir == "" {
			continue
		}
		rel, err := filepath.Rel(m.Dir, dir)
		if err != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
			continue
		}
		if rel == "." {
			return m.Path, true
		}
		return m.Path + "/" + filepath.ToSlash(rel), true
	}
	}
	return "", false
}

// runContainsQueries resolves file= patterns.
func (state *golistState) runContainsQueries(response *driverResponse, seenIDs map[string]bool, queries []string) error {
	for _, query := range queries {
		fdir := filepath.Dir(query)
		pattern, err := filepath.Abs(fdir)
		if err != nil {
			return fmt.Errorf("could not determine absolute path of file= query path %q: %v", query, err)
		}
		dirResponse, err := state.createDriverResponse(pattern)
		if err != nil || len(dirResponse.Packages) == 0 || len(dirResponse.Packages) == 1 && len(dirResponse.Packages[0].GoFiles) == 0 &&
			len(dirResponse.Packages[0].Errors) == 1 {
			var queryErr error
			if dirResponse, queryErr = state.adhocPackage(pattern, query); queryErr != nil {
				return err
			}
		}
		isRoot := make(map[string]bool, len(dirResponse.Roots))
		for _, root := range dirResponse.Roots {
			isRoot[root] = true
		}
		for _, pkg := range dirResponse.Packages {
			if !seenIDs[pkg.ID] {
				seenIDs[pkg.ID] = true
				response.Packages = append(response.Packages, pkg)
			}
			if !isRoot[pkg.ID] {
				continue
			}
			for _, pkgFile := range pkg.GoFiles {
				if filepath.Base(query) == filepath.Base(pkgFile) {
					if !containsString(response.Roots, pkg.ID) {
						response.Roots = append(response.Roots, pkg.ID)
					}
					break
				}
			}
		}
	}
	return nil
}

func (state *golistState) adhocPackage(pattern, query string) (*driverResponse, error) {
	response, err := state.createDriverResponse(query)
	if err != nil {
		return nil, err
	}
	if len(response.Packages) == 0 {
		response.Packages = append(response.Packages, &Package{
			ID:              "command-line-arguments",
			PkgPath:         query,
			GoFiles:         []string{query},
			CompiledGoFiles: []string{query},
			Imports:         make(map[string]*Package),
		})
		response.Roots = append(response.Roots, "command-line-arguments")
	}
	if len(response.Packages) == 1 {
		if response.Packages[0].Errors == nil {
			response.Packages[0].Errors = []Error{}
		}
	}
	return response, nil
}

func containsString(list []string, s string) bool {
	for _, x := range list {
		if x == s {
			return true
		}
	}
	return false
}

// driver resolves patterns into a driver response.
func (state *golistState) driver(patterns []string) (*driverResponse, error) {
	var containFiles []string
	restPatterns := make([]string, 0, len(patterns))
extractQueries:
	for _, pattern := range patterns {
		eqidx := strings.Index(pattern, "=")
		if eqidx < 0 {
			restPatterns = append(restPatterns, pattern)
		} else {
			query, value := pattern[:eqidx], pattern[eqidx+len("="):]
			switch query {
			case "file":
				containFiles = append(containFiles, value)
			case "pattern":
				restPatterns = append(restPatterns, value)
			case "":
				restPatterns = append(restPatterns, pattern)
			default:
				for _, r := range query {
					if r < 'a' || r > 'z' {
						restPatterns = append(restPatterns, pattern)
						continue extractQueries
					}
				}
				return nil, fmt.Errorf("invalid query type %q in query pattern %q", query, pattern)
			}
		}
	}

	var compiler, arch string
	var sizesErr error
	if !state.cfg.NoTypes {
		compiler, arch, sizesErr = state.getSizes()
	}

	response := &driverResponse{}
	seenIDs := make(map[string]bool)
	if len(restPatterns) > 0 || len(patterns) == 0 {
		dr, err := state.createDriverResponse(restPatterns...)
		if err != nil {
			if sizesErr != nil {
				return nil, sizesErr
			}
			return nil, err
		}
		response.GoVersion = dr.GoVersion
		for _, pkg := range dr.Packages {
			seenIDs[pkg.ID] = true
			response.Packages = append(response.Packages, pkg)
		}
		response.Roots = append(response.Roots, dr.Roots...)
	}
	if len(containFiles) != 0 {
		if err := state.runContainsQueries(response, seenIDs, containFiles); err != nil {
			if sizesErr != nil {
				return nil, sizesErr
			}
			return nil, err
		}
		if v, err := state.getGoVersion(); err == nil {
			response.GoVersion = v
		}
	}
	if sizesErr != nil {
		return nil, sizesErr
	}
	response.Compiler, response.Arch = compiler, arch
	return response, nil
}
