// moduleGoFiles lists the Go files under a module root the way ./... walks
// it: no testdata, vendor, hidden or underscore directories, and no nested
// modules.
func moduleGoFiles(root string) []string {
	var out []string
	filepath.WalkDir(root, func(path string, d os.DirEntry, err error) error {
		if err != nil {
			return nil
		}
		name := d.Name()
		if d.IsDir() {
			if path == root {
				return nil
			}
			if strings.HasPrefix(name, ".") || strings.HasPrefix(name, "_") || name == "testdata" || name == "vendor" {
				return filepath.SkipDir
			}
			if _, err := os.Stat(filepath.Join(path, "go.mod")); err == nil {
				return filepath.SkipDir
			}
			return nil
		}
		if strings.HasSuffix(name, ".go") && !strings.HasPrefix(name, ".") && !strings.HasPrefix(name, "_") {
			out = append(out, path)
		}
		return nil
	})
	return out
}

func (st *shrinkState) readExcluded(path string, byDir map[string]*shrinkUnit) {
	f, err := parser.ParseFile(token.NewFileSet(), path, nil, parser.SkipObjectResolution)
	if f == nil || f.Name == nil {
		_ = err
		return
	}
	if su := byDir[filepath.Dir(path)]; su != nil && (f.Name.Name == su.pkg.Name) {
		names := st.ownNames[su]
		if names == nil {
			names = make(map[string]bool)
			st.ownNames[su] = names
		}
		ast.Inspect(f, func(n ast.Node) bool {
			if id, ok := n.(*ast.Ident); ok {
				names[id.Name] = true
			}
			return true
		})
		return
	}
	imports := make(map[string]*shrinkUnit)
	for _, is := range f.Imports {
		p, err := strconv.Unquote(is.Path.Value)
		if err != nil {
			continue
		}
		su := st.byPath[p]
		if su == nil {
			continue
		}
		name := su.pkg.Name
		if is.Name != nil {
			name = is.Name.Name
		}
		imports[name] = su
	}
	if len(imports) == 0 {
		return
	}
	ast.Inspect(f, func(n ast.Node) bool {
		sel, ok := n.(*ast.SelectorExpr)
		if !ok {
			return true
		}
		x, ok := sel.X.(*ast.Ident)
		if !ok {
			return true
		}
		su := imports[x.Name]
		if su == nil {
			return true
		}
		obj := su.pkg.Types.Scope().Lookup(sel.Sel.Name)
		if obj == nil {
			return true
		}
