package analyzer

import (
	"go/ast"
	"go/token"
	"go/types"
)

// conversions calls found for every value a file converts to an interface
// type: the concrete type of the value and the interface. Go converts
// implicitly on assignment, on passing an argument or returning a result,
// inside composite literals, on sends, on comparisons with an interface,
// and explicitly with a conversion. live is false for a conversion whose
// result is discarded at once, as on assignment to the blank identifier,
// or that sits in a function literal nothing calls or keeps.
func conversions(info *types.Info, file *ast.File, found func(src, iface types.Type, live bool)) {
	live := true
	deadLits := deadFuncLits(info, file)
	blank := false
	check := func(src ast.Expr, dst types.Type) {
		if src == nil || dst == nil {
			return
		}
		if !types.IsInterface(dst) {
			return
		}
		tv, ok := info.Types[src]
		if !ok || tv.Type == nil || tv.IsNil() {
			return
		}
		if types.IsInterface(tv.Type) {
			return
		}
		if _, ok := tv.Type.(*types.TypeParam); ok {
			return
		}
		found(tv.Type, dst, live && !blank)
	}
	typeOf := func(e ast.Expr) types.Type {
		if tv, ok := info.Types[e]; ok {
			return tv.Type
		}
		if id, ok := e.(*ast.Ident); ok {
			if obj := info.Defs[id]; obj != nil {
				return obj.Type()
			}
			if obj := info.Uses[id]; obj != nil {
				return obj.Type()
			}
		}
		return nil
	}
	var funcs []*types.Signature
	var visit func(n ast.Node) bool
	visit = func(n ast.Node) bool {
		switch n := n.(type) {
		case *ast.FuncDecl:
			if obj, ok := info.Defs[n.Name].(*types.Func); ok {
				funcs = append(funcs, obj.Type().(*types.Signature))
				if n.Body != nil {
					ast.Inspect(n.Body, visit)
				}
				funcs = funcs[:len(funcs)-1]
			}
			return false
		case *ast.FuncLit:
			if sig, ok := typeOf(n).(*types.Signature); ok {
				funcs = append(funcs, sig)
				saved := live
				if deadLits[n] {
					live = false
				}
				ast.Inspect(n.Body, visit)
				live = saved
				funcs = funcs[:len(funcs)-1]
			}
			return false
		case *ast.AssignStmt:
			if n.Tok == token.ASSIGN && len(n.Lhs) == len(n.Rhs) {
				for i := range n.Lhs {
					blank = isBlank(n.Lhs[i])
					check(n.Rhs[i], typeOf(n.Lhs[i]))
					blank = false
				}
			}
		case *ast.ValueSpec:
			if n.Type != nil && len(n.Values) == len(n.Names) {
				t := typeOf(n.Type)
				for i, v := range n.Values {
					blank = n.Names[i].Name == "_"
					check(v, t)
					blank = false
				}
			}
		case *ast.ReturnStmt:
			if len(funcs) == 0 {
				break
			}
			res := funcs[len(funcs)-1].Results()
			if res != nil && res.Len() == len(n.Results) {
				for i, r := range n.Results {
					check(r, res.At(i).Type())
				}
			}
		case *ast.CallExpr:
			callConversions(info, n, check, typeOf)
		case *ast.CompositeLit:
			t := typeOf(n)
			if t == nil {
				break
			}
			u := t.Underlying()
			if p, ok := u.(*types.Pointer); ok {
				u = p.Elem().Underlying()
			}
			switch u := u.(type) {
			case *types.Struct:
				for i, e := range n.Elts {
					if kv, ok := e.(*ast.KeyValueExpr); ok {
						if id, ok := kv.Key.(*ast.Ident); ok {
							if f, ok := info.Uses[id].(*types.Var); ok {
								check(kv.Value, f.Type())
							}
						}
					} else if i < u.NumFields() {
						check(e, u.Field(i).Type())
					}
				}
			case *types.Slice:
				elemConv(n.Elts, u.Elem(), check)
			case *types.Array:
				elemConv(n.Elts, u.Elem(), check)
			case *types.Map:
				for _, e := range n.Elts {
					if kv, ok := e.(*ast.KeyValueExpr); ok {
						check(kv.Key, u.Key())
						check(kv.Value, u.Elem())
					}
				}
			}
		case *ast.SendStmt:
			if ch, ok := typeOf(n.Chan).Underlying().(*types.Chan); ok {
				check(n.Value, ch.Elem())
			}
		case *ast.BinaryExpr:
			if n.Op == token.EQL || n.Op == token.NEQ {
				check(n.X, typeOf(n.Y))
				check(n.Y, typeOf(n.X))
			}
		case *ast.IndexExpr:
			if t := typeOf(n.X); t != nil {
				if m, ok := t.Underlying().(*types.Map); ok {
					check(n.Index, m.Key())
				}
			}
		case *ast.SwitchStmt:
			if n.Tag != nil {
				tag := typeOf(n.Tag)
				for _, s := range n.Body.List {
					if cc, ok := s.(*ast.CaseClause); ok {
						for _, e := range cc.List {
							check(e, tag)
						}
					}
				}
			}
		}
		return true
	}
	ast.Inspect(file, visit)
}

func isBlank(e ast.Expr) bool {
	id, ok := ast.Unparen(e).(*ast.Ident)
	return ok && id.Name == "_"
}

// deadFuncLits finds the function literals whose value is thrown away: assigned
// to the blank identifier, or to a local variable nothing reads but the
// blank identifier. Nothing can call them.
func deadFuncLits(info *types.Info, file *ast.File) map[*ast.FuncLit]bool {
	dead := make(map[*ast.FuncLit]bool)
	// Count, for every local variable, the reads that do not just discard it.
	reads := make(map[types.Object]int)
	discards := make(map[*ast.Ident]bool)
	ast.Inspect(file, func(n ast.Node) bool {
		if as, ok := n.(*ast.AssignStmt); ok && len(as.Lhs) == len(as.Rhs) {
			for i := range as.Lhs {
				if isBlank(as.Lhs[i]) {
					if id, ok := ast.Unparen(as.Rhs[i]).(*ast.Ident); ok {
						discards[id] = true
					}
				}
			}
		}
		if id, ok := n.(*ast.Ident); ok && !discards[id] {
			if obj := info.Uses[id]; obj != nil {
				reads[obj]++
			}
		}
		return true
	})
	consider := func(lhs []ast.Expr, rhs []ast.Expr, define bool) {
		if len(lhs) != len(rhs) {
			return
		}
		for i, r := range rhs {
			lit, ok := ast.Unparen(r).(*ast.FuncLit)
			if !ok {
				continue
			}
			if isBlank(lhs[i]) {
				dead[lit] = true
				continue
			}
			id, ok := lhs[i].(*ast.Ident)
			if !ok {
				continue
			}
			obj := info.Defs[id]
			if obj == nil {
				obj = info.Uses[id]
			}
			if v, ok := obj.(*types.Var); ok && v.Parent() != nil && v.Parent() != v.Pkg().Scope() && reads[obj] == 0 {
				dead[lit] = true
			}
		}
	}
	ast.Inspect(file, func(n ast.Node) bool {
		switch n := n.(type) {
		case *ast.AssignStmt:
			consider(n.Lhs, n.Rhs, n.Tok == token.DEFINE)
		case *ast.ValueSpec:
			var lhs []ast.Expr
			for _, id := range n.Names {
				lhs = append(lhs, id)
			}
			consider(lhs, n.Values, true)
		}
		return true

// Package diff computes edits between texts, applies and merges them, and
// renders unified diffs.
package diff

import (
	"fmt"
	"slices"
	"sort"
	"strings"
	"unicode/utf8"
)

// An Edit replaces src[Start:End] by New.
type Edit struct {
	Start, End int
	New        string
}

// Strings computes the edits that turn before into after.
// The edits respect rune boundaries.
func Strings(before, after string) []Edit {
	if before == after {
		return nil
	}
	if isASCII(before) && isASCII(after) {
		a, b := []byte(before), []byte(after)
		diffs := lcsDiffs(bytesSeqs{a, b})
		res := make([]Edit, len(diffs))
		for i, d := range diffs {
			res[i] = Edit{d.Start, d.End, string(b[d.ReplStart:d.ReplEnd])}
		}
		return res
	}
	a, b := []rune(before), []rune(after)
	diffs := lcsDiffs(runesSeqs{a, b})
	res := make([]Edit, len(diffs))
	lastEnd := 0
	utf8Len := 0
	for i, d := range diffs {
		utf8Len += runesLen(a[lastEnd:d.Start])
		start := utf8Len
		utf8Len += runesLen(a[d.Start:d.End])
		res[i] = Edit{start, utf8Len, string(b[d.ReplStart:d.ReplEnd])}
		lastEnd = d.End
	}
	return res
}

// Lines computes the edits that turn before into after, a whole line at a
// time.
func Lines(before, after string) []Edit {
	if before == after {
		return nil
	}
	a, offsets := linesOf(before)
	b, _ := linesOf(after)
	diffs := lcsDiffs(linesSeqs{a, b})
	res := make([]Edit, len(diffs))
	for i, d := range diffs {
		res[i] = Edit{
			Start: offsets[d.Start],
			End:   offsets[d.End],
			New:   strings.Join(b[d.ReplStart:d.ReplEnd], ""),
		}
	}
	return res
}

// linesOf splits text into lines that keep their newlines, with the offset
// of the start of each line and of the end of the text.
func linesOf(text string) ([]string, []int) {
	var lines []string
	offsets := []int{0}
	for text != "" {
		i := strings.IndexByte(text, '\n') + 1
		if i == 0 {
			i = len(text)
		}
		lines = append(lines, text[:i])
		offsets = append(offsets, offsets[len(offsets)-1]+i)
		text = text[i:]
	}
	return lines, offsets
}

func runesLen(runes []rune) (n int) {
	for _, r := range runes {
		n += utf8.RuneLen(r)
	}
	return n
}

func isASCII(s string) bool {
	for i := 0; i < len(s); i++ {
		if s[i] >= utf8.RuneSelf {
			return false
		}
	}
	return true
}

type editsSort []Edit

func (a editsSort) Len() int { return len(a) }
func (a editsSort) Less(i, j int) bool {
	if a[i].Start != a[j].Start {
		return a[i].Start < a[j].Start
	}
	return a[i].End < a[j].End
}
func (a editsSort) Swap(i, j int) { a[i], a[j] = a[j], a[i] }

// SortEdits orders edits by (start, end), stably.
func SortEdits(edits []Edit) { sort.Stable(editsSort(edits)) }

func validate(src string, edits []Edit) ([]Edit, int, error) {
	if !sort.IsSorted(editsSort(edits)) {
		edits = slices.Clone(edits)
		SortEdits(edits)
	}
	size := len(src)
	lastEnd := 0
	for _, edit := range edits {
		if !(0 <= edit.Start && edit.Start <= edit.End && edit.End <= len(src)) {
			return nil, 0, fmt.Errorf("diff has out-of-bounds edits")
		}
		if edit.Start < lastEnd {
			return nil, 0, fmt.Errorf("diff has overlapping edits")
		}
		size += len(edit.New) + edit.Start - edit.End
		lastEnd = edit.End
	}
	return edits, size, nil
}

// Apply applies edits to src.
func Apply(src string, edits []Edit) (string, error) {
	edits, size, err := validate(src, edits)
	if err != nil {
		return "", err
	}
	out := make([]byte, 0, size)
	lastEnd := 0
	for _, edit := range edits {
		if lastEnd < edit.Start {
			out = append(out, src[lastEnd:edit.Start]...)
		}
		out = append(out, edit.New...)
		lastEnd = edit.End
	}
	out = append(out, src[lastEnd:]...)
	return string(out), nil
}

// ApplyBytes is Apply for byte slices.
func ApplyBytes(src []byte, edits []Edit) ([]byte, error) {
	res, err := Apply(string(src), edits)
	return []byte(res), err
}

// Merge merges two valid, ordered lists of edits. It reports false on a
// conflict. Identical edits are coalesced.
func Merge(x, y []Edit) ([]Edit, bool) {
	x = slices.Clone(x)
	y = slices.Clone(y)
	var merged []Edit
	add := func(edit Edit) { merged = append(merged, edit) }
	var xi, yi int
	for xi < len(x) && yi < len(y) {
		px := &x[xi]
		py := &y[yi]
		if *px == *py {
			add(*px)
			xi++
			yi++
		} else if px.End <= py.Start {
			add(*px)
			xi++
		} else if py.End <= px.Start {
			add(*py)
			yi++
		} else if px.Start < py.Start {
			add(Edit{px.Start, py.Start, ""})
			px.Start = py.Start
		} else if py.Start < px.Start {
			add(Edit{py.Start, px.Start, ""})
			py.Start = px.Start
		} else {
			return nil, false
		}
	}
	for ; xi < len(x); xi++ {
		add(x[xi])
	}
	for ; yi < len(y); yi++ {
		add(y[yi])
	}
	return merged, true
}

// lineEdits expands and merges edits so that each replaces whole lines.
func lineEdits(src string, edits []Edit) ([]Edit, error) {
	edits, _, err := validate(src, edits)
	if err != nil {
		return nil, err
	}
	for _, edit := range edits {
		if edit.Start >= len(src) ||
			edit.Start > 0 && src[edit.Start-1] != '\n' ||
			edit.End > 0 && src[edit.End-1] != '\n' ||
			edit.New != "" && edit.New[len(edit.New)-1] != '\n' {
			goto expand
		}
	}
	return edits, nil

expand:
	if len(edits) == 0 {
		return edits, nil
	}
	expanded := make([]Edit, 0, len(edits))
	prev := edits[0]
	for _, edit := range edits[1:] {
		between := src[prev.End:edit.Start]
		if !strings.Contains(between, "\n") {
			prev.New += between + edit.New
			prev.End = edit.End
		} else {
			expanded = append(expanded, expandEdit(prev, src))
			prev = edit
		}
	}
	return append(expanded, expandEdit(prev, src)), nil
}

func expandEdit(edit Edit, src string) Edit {
	start := edit.Start
	if delta := start - 1 - strings.LastIndex(src[:start], "\n"); delta > 0 {
		edit.Start -= delta
		edit.New = src[start-delta:start] + edit.New
	}
	end := edit.End
	if end > 0 && src[end-1] != '\n' ||
		edit.New != "" && edit.New[len(edit.New)-1] != '\n' {
		if nl := strings.IndexByte(src[end:], '\n'); nl < 0 {
			edit.End = len(src)
		} else {
			edit.End = end + nl + 1
		}
	}
package diff

import (
	"fmt"
	"sort"
)

// This file computes a longest common subsequence of two sequences with a
// two-sided Myers search that gives up after a fixed number of differences.
// Its choices among equally long subsequences determine the shape of every
// printed diff, so the search order below is deliberate.

// lcsDiff is a replacement of a[Start:End] by b[ReplStart:ReplEnd].
type lcsDiff struct {
	Start, End         int
	ReplStart, ReplEnd int
}

// A diag is a run where a[X+i] == b[Y+i] for 0 <= i < Len.
type diag struct {
	X, Y int
	Len  int
}

type lcs []diag

func (l lcs) sort() lcs {
	sort.Slice(l, func(i, j int) bool {
		if l[i].X != l[j].X {
			return l[i].X < l[j].X
		}
		return l[i].Len > l[j].Len
	})
	return l
}

// fix repairs an lcs whose parts may overlap, which happens when the
// two-sided search stops early.
func (l lcs) fix() lcs {
	if len(l) == 0 {
		return nil
	}
	sort.Slice(l, func(i, j int) bool { return l[i].Len > l[j].Len })
	tmp := make(lcs, 0, len(l))
	tmp = append(tmp, l[0])
	for i := 1; i < len(l); i++ {
		var dir direction
		nxt := l[i]
		for _, in := range tmp {
			if dir, nxt = overlap(in, nxt); dir == empty || dir == bad {
				break
			}
		}
		if nxt.Len > 0 && dir != bad {
			tmp = append(tmp, nxt)
		}
	}
	tmp.sort()
	return tmp
}

type direction int

const (
	empty direction = iota
	leftdown
	rightup
	bad
)

// overlap trims prop so that it does not overlap exist.
func overlap(exist, prop diag) (direction, diag) {
	if prop.X <= exist.X && exist.X < prop.X+prop.Len {
		delta := prop.X + prop.Len - exist.X
		prop.Len -= delta
		if prop.Len <= 0 {
			return empty, prop
		}
	}
	if exist.X <= prop.X && prop.X < exist.X+exist.Len {
		delta := exist.X + exist.Len - prop.X
		prop.Len -= delta
		if prop.Len <= 0 {
			return empty, prop
		}
		prop.X += delta
		prop.Y += delta
	}
	if prop.Y <= exist.Y && exist.Y < prop.Y+prop.Len {
		delta := prop.Y + prop.Len - exist.Y
		prop.Len -= delta
		if prop.Len <= 0 {
			return empty, prop
		}
	}
	if exist.Y <= prop.Y && prop.Y < exist.Y+exist.Len {
		delta := exist.Y + exist.Len - prop.Y
		prop.Len -= delta
		if prop.Len <= 0 {
			return empty, prop
		}
		prop.X += delta
		prop.Y += delta
	}
	if prop.X+prop.Len <= exist.X && prop.Y+prop.Len <= exist.Y {
		return leftdown, prop
	}
	if exist.X+exist.Len <= prop.X && exist.Y+exist.Len <= prop.Y {
		return rightup, prop
	}
	return bad, prop
}

func (l lcs) prepend(x, y int) lcs {
	if len(l) > 0 {
		d := &l[0]
		if d.X == x+1 && d.Y == y+1 {
			d.X, d.Y = x, y
			d.Len++
			return l
		}
	}
	r := diag{X: x, Y: y, Len: 1}
	return append([]diag{r}, l...)
}

func (l lcs) append(x, y int) lcs {
	if len(l) > 0 {
		last := &l[len(l)-1]
		if last.X+last.Len == x && last.Y+last.Len == y {
			last.Len++
			return l
		}
	}
	return append(l, diag{X: x, Y: y, Len: 1})
}

func ok(d, k int) bool {
	return d >= 0 && -d <= k && k <= d
}

func (l lcs) toDiffs(alen, blen int) []lcsDiff {
	var diffs []lcsDiff
	var pa, pb int
	for _, d := range l {
		if pa < d.X || pb < d.Y {
			diffs = append(diffs, lcsDiff{pa, d.X, pb, d.Y})
		}
		pa = d.X + d.Len
		pb = d.Y + d.Len
	}
	if pa < alen || pb < blen {
		diffs = append(diffs, lcsDiff{pa, alen, pb, blen})
	}
	return diffs
}

