// insertDirective writes a directive on its own line above a target.
func (m *model) insertDirective(t *target, text string) checker.TextEdit {
	pos := t.node.Pos()
	tf := m.fset.File(pos)
	src := m.source(tf.Name())
	off := tf.Offset(pos)
	lineStart := off
	for lineStart > 0 && src[lineStart-1] != '\n' {
